/* Dialectica fact-check: what was checked against published scholarship, the verdict and the sources, in English and Chinese. Edit freely, then run `node scripts/check-data.mjs`. */
window.DIALECTICA = window.DIALECTICA || {};
window.DIALECTICA.facts = [
  {"about":"thinker:pythagoras","verdict":"confirmed","claim":{"en":"The idea that all things are number is attested for Pythagoras’ followers rather than for Pythagoras himself.","zh":"“万物皆数”的说法见于毕达哥拉斯的追随者，而非确凿出自毕达哥拉斯本人。"},"finding":{"en":"Pythagoras wrote nothing and no contemporary account survives; fuller lives date from 150 to 800 years after his death. Aristotle ascribes the view that things are numbers to the “so-called Pythagoreans” of the 5th century, and Philolaus’ genuine fragments say only that whatever is known has number.","zh":"毕达哥拉斯没有留下著作，也没有同时代的记载传世；较完整的传记写于他死后150到800年间。亚里士多德把“事物即数”归于5世纪的“所谓毕达哥拉斯派”，而菲洛劳斯的可靠残篇只说“凡被认识的事物都有数”。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Pythagoras”","url":"https://plato.stanford.edu/entries/pythagoras/"},{"title":"Stanford Encyclopedia of Philosophy, “Philolaus”","url":"https://plato.stanford.edu/entries/philolaus/"}]},
  {"about":"thinker:thales","verdict":"contested","claim":{"en":"Ancient reports credit Thales with predicting an eclipse, usually dated to 585 BCE.","zh":"古代记载称泰勒斯预言了一次日食，通常定为公元前585年。"},"finding":{"en":"Herodotus says Thales foretold the eclipse that ended a battle between the Lydians and the Medes, conventionally 28 May 585 BCE. The eclipse itself is secure, but historians doubt that any method available to him, such as the Babylonian cycles, could have predicted a solar eclipse for that place; whether he really did so is open.","zh":"希罗多德说泰勒斯预言了那次让吕底亚人与米底人停战的日食，通常定为公元前585年5月28日。日食本身确有其事，但史家怀疑他当时可用的任何方法（例如巴比伦的周期）都无法预测该地会出现日全食，因此他是否真的预言过仍无定论。"},"sources":[{"title":"Internet Encyclopedia of Philosophy, “Thales of Miletus”","url":"https://iep.utm.edu/thales/"}]},
  {"about":"tie:antisthenes>diogenes","verdict":"contested","claim":{"en":"Ancient tradition makes Diogenes Antisthenes’ pupil.","zh":"古代传统认为第欧根尼是安提斯泰尼的学生。"},"finding":{"en":"The line Socrates → Antisthenes → Diogenes comes from Diogenes Laertius, who “controversially” names Antisthenes the first Cynic. Plato and Xenophon never call Antisthenes a “dog”, and modern scholars treat the succession as a later construction that tracks real intellectual kinship rather than a documented teacher–pupil bond.","zh":"苏格拉底→安提斯泰尼→第欧根尼这一传承出自第欧根尼·拉尔修，他把安提斯泰尼称作第一位犬儒，这一点颇受争议。柏拉图与色诺芬从未称安提斯泰尼为“狗”；现代学者认为这条师承是后人构建的，反映的是思想上的亲缘，而不是有据可查的师生关系。"},"sources":[{"title":"Internet Encyclopedia of Philosophy, “Cynics”","url":"https://iep.utm.edu/cynics/"}]},
  {"about":"tie:heraclitus>parmenides","verdict":"contested","claim":{"en":"Parmenides’ attack on “two-headed mortals” is often, though debatably, read as aimed at Heraclitus.","zh":"巴门尼德对“双头凡人”的抨击，常被（但有争议地）解读为针对赫拉克利特。"},"finding":{"en":"Fragment 6 condemns mortals for whom “to be and not to be are the same and not the same” but names no one. Some scholars hear Heraclitus in it; others see a general target, and recent work stresses how much the two thinkers share. Even their relative dates are uncertain.","zh":"残篇6谴责那些认为“存在与不存在既相同又不相同”的凡人，但没有点名。有学者听出其中针对赫拉克利特，也有人认为目标是一般人；近来的研究还强调两人之间的共同之处。连他们孰先孰后都不能确定。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Parmenides”","url":"https://plato.stanford.edu/entries/parmenides/"},{"title":"Stanford Encyclopedia of Philosophy, “Heraclitus”","url":"https://plato.stanford.edu/entries/heraclitus/"}]},
  {"about":"tie:empedocles>gorgias","verdict":"uncertain","claim":{"en":"According to ancient report, Gorgias studied with Empedocles.","zh":"据古代记载，高尔吉亚曾师从恩培多克勒。"},"finding":{"en":"The report goes back to the Hellenistic biographer Satyrus, quoted by Diogenes Laertius (8.58), and is repeated by later writers. The two were near contemporaries, and modern reference works range from accepting it to calling it a biographer’s tale; the atlas keeps the tie but marks it as a report.","zh":"这一说法源自希腊化时期的传记作者萨提洛斯，由第欧根尼·拉尔修（8.58）转引，后世作者沿袭。两人年龄相近；现代工具书有的照录，有的视为传记家的附会。本图谱保留这条关系，但注明它只是一种记载。"},"sources":[{"title":"Diogenes Laertius, Lives of the Eminent Philosophers 8.58 (trans. R. D. Hicks, LacusCurtius)","url":"https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Diogenes_Laertius/Lives_of_the_Eminent_Philosophers/8/Empedocles*.html"},{"title":"Internet Encyclopedia of Philosophy, “Gorgias”","url":"https://iep.utm.edu/gorgias/"}]},
  {"about":"thinker:pyrrho","verdict":"contested","claim":{"en":"Ancient sources say Pyrrho met Indian “naked sages”; whether this shaped his views is debated.","zh":"古代资料说皮浪见过印度的“裸体智者”；这是否影响了他的思想仍有争议。"},"finding":{"en":"Pyrrho (c. 365/360–275/270 BCE) went to India with Alexander together with his teacher Anaxarchus, a Democritean; that much is well attested. Diogenes Laertius says the meeting with the gymnosophists shaped his philosophy, but we do not know who they were. C. I. Beckwith (2015) argues Pyrrho was in effect an early Buddhist; most specialists find the parallels suggestive but unproven.","zh":"皮浪（约公元前365/360–前275/270年）与他的老师、德谟克利特派的阿那克萨库斯一同随亚历山大到过印度，这一点证据充分。第欧根尼·拉尔修说与“裸体智者”的相遇塑造了他的哲学，但我们不知道这些智者是谁。白桂思（2015）认为皮浪实际上是早期佛教的代表；多数专家认为相似之处值得注意，但尚未得到证明。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Pyrrho”","url":"https://plato.stanford.edu/entries/pyrrho/"}]},
  {"about":"thinker:leucippus","verdict":"uncertain","claim":{"en":"Leucippus founded atomism in the 5th century BCE; Epicurus is reported to have doubted he existed.","zh":"留基伯在公元前5世纪创立原子论；据说伊壁鸠鲁怀疑过他是否存在。"},"finding":{"en":"Nothing firm is known of his dates or birthplace; ancient reports make him a pupil of Zeno of Elea and the teacher of Democritus. Epicurus apparently denied there had been a philosopher Leucippus, and some 19th-century scholars agreed, but Aristotle and Theophrastus treat him as real. The one surviving sentence, from a work On Mind, says nothing happens in vain (or at random) but everything from reason and by necessity.","zh":"他的生卒年与出生地都无确切记载；古代资料说他是爱利亚的芝诺的学生、德谟克利特的老师。伊壁鸠鲁似乎否认有过留基伯这位哲学家，19世纪也有学者附和，但亚里士多德与泰奥弗拉斯托斯都把他当作真实人物。他唯一传世的一句话出自《论心灵》：没有什么是无端（或偶然）发生的，一切都出于理由并出于必然。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Leucippus”","url":"https://plato.stanford.edu/entries/leucippus/"}]},
  {"about":"thinker:sextus-empiricus","verdict":"corrected","claim":{"en":"Sextus Empiricus flourished c. 200 CE.","zh":"塞克斯都·恩披里柯约公元200年前后在世。"},"finding":{"en":"Nothing in his works fixes his dates. Estimates run from about 100 CE to the first half of the 3rd century, and he may already have been known by the end of the 2nd; “c. 200” is a convenient middle, not evidence. His name marks him as a doctor of the Empiric school of medicine.","zh":"他的著作中没有任何能确定年代的线索。学者的估计从约公元100年一直到3世纪上半叶，他可能在2世纪末已有名声；“约200年”只是方便的折中，并非证据。他的名字表明他是医学“经验派”的医生。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Sextus Empiricus”","url":"https://plato.stanford.edu/entries/sextus-empiricus/"}]},
  {"about":"thinker:hypatia","verdict":"corrected","claim":{"en":"Hypatia was born c. 360.","zh":"希帕提娅约生于360年。"},"finding":{"en":"Her birth year is unknown: suggestions range from about 350 to 370 (MacTutor follows Mueller’s “370?”; Maria Dzielska argued for about 355). Her death in March 415 at the hands of a Christian mob, amid the feud between the bishop Cyril and the prefect Orestes, is well attested. None of her writings survives; she worked with her father Theon on commentaries on Ptolemy and Euclid.","zh":"她的出生年份不详：学者的推断从约350年到370年不等（MacTutor采用米勒“约370年？”之说，玛丽亚·杰尔斯卡则主张约355年）。她于415年3月被一群基督徒暴民杀害，背景是主教西里尔与总督俄瑞斯忒斯之争，这一点有充分记载。她的著作无一传世；她曾协助父亲席翁注释托勒密与欧几里得。"},"sources":[{"title":"MacTutor History of Mathematics, “Hypatia of Alexandria”","url":"https://mathshistory.st-andrews.ac.uk/Biographies/Hypatia/"}]},
  {"about":"thinker:plato","verdict":"confirmed","claim":{"en":"The years given for Plato’s dialogues (Symposium c. 385, Phaedo c. 380, Republic c. 375 BCE) are approximate.","zh":"柏拉图对话的年代（《会饮篇》约前385年、《斐多篇》约前380年、《理想国》约前375年）只是近似值。"},"finding":{"en":"No dialogue is securely dated. The usual early, middle and late grouping rests on ancient testimony that the Laws came last and on stylometric study of the Greek; it remains disputed whether it reflects the order of composition. The atlas’s years follow the common view that the Symposium, Phaedo and Republic belong to the middle period.","zh":"没有一篇对话的年代能够确定。通行的早、中、晚期划分，依据的是《法篇》为最后之作的古代证词，以及对希腊原文的文体统计研究；这种划分是否反映写作顺序仍有争议。本图谱的年份采用通行看法，即《会饮篇》《斐多篇》《理想国》属于中期。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Plato”","url":"https://plato.stanford.edu/entries/plato/"}]},
  {"about":"school:cynicism","verdict":"confirmed","claim":{"en":"No primary texts by Antisthenes or Diogenes survive, so the Cynic works list is empty.","zh":"安提斯泰尼与第欧根尼的原著均未传世，因此犬儒学派的著作列表为空。"},"finding":{"en":"Ancient catalogues list many Cynic writings, but none survives; Cynicism is known through anecdotes and sayings, above all in Diogenes Laertius, Book 6.","zh":"古代书目列有大量犬儒著作，但无一传世；我们对犬儒主义的了解来自轶事与语录，主要见于第欧根尼·拉尔修《名哲言行录》第6卷。"},"sources":[{"title":"Internet Encyclopedia of Philosophy, “Cynics”","url":"https://iep.utm.edu/cynics/"}]},
  {"about":"school:pythagorean","verdict":"confirmed","claim":{"en":"The Pythagorean school lists only one primary text, Philolaus’ fragments.","zh":"毕达哥拉斯学派只列出了一部原始文本，即菲洛劳斯的残篇。"},"finding":{"en":"Pythagoras wrote nothing, and books later circulated under his name are judged forgeries. Philolaus’ On Nature was probably the first book written by a Pythagorean; about eleven of its fragments are accepted as genuine.","zh":"毕达哥拉斯没有著作，后世以他名义流传的书被判定为伪作。菲洛劳斯的《论自然》大概是第一部由毕达哥拉斯派写成的书，其中约十一则残篇被认为可靠。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Pythagoras”","url":"https://plato.stanford.edu/entries/pythagoras/"},{"title":"Stanford Encyclopedia of Philosophy, “Philolaus”","url":"https://plato.stanford.edu/entries/philolaus/"}]},
  {"about":"link:atomism>epicureanism","verdict":"corrected","claim":{"en":"Epicurus added a slight “swerve” of atoms to make room for free choice.","zh":"伊壁鸠鲁加入原子微小的“偏斜”，为自由选择留出空间。"},"finding":{"en":"The swerve is not described in Epicurus’ surviving letters; it is known chiefly from Lucretius and Cicero, who attribute it to him. Scholars generally accept it as Epicurean doctrine, but its exact form is unclear.","zh":"“偏斜”并不见于伊壁鸠鲁传世的书信，主要通过卢克莱修与西塞罗得知，他们都说这是伊壁鸠鲁的学说。学者一般承认这是伊壁鸠鲁派的教义，但它的确切形式并不清楚。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Epicurus”","url":"https://plato.stanford.edu/entries/epicurus/"}]},
  {"about":"school:platonism","verdict":"contested","claim":{"en":"Platonism (the Academy) runs from 387 BCE to the 6th century CE.","zh":"柏拉图主义（学园）从公元前387年延续到公元6世纪。"},"finding":{"en":"Plato’s own Academy did not last that long: its head Philo of Larissa left Athens in 88 BCE and Sulla ravaged the grove in 86 BCE. A Platonist school was refounded in Athens around 410 CE and closed under Justinian in 529, but historians find no institutional continuity between the two. The block’s end date marks the Athenian school’s closure; Platonism as a philosophy never stopped.","zh":"柏拉图本人的学园并没有延续那么久：学园领袖拉里萨的斐洛于公元前88年离开雅典，公元前86年苏拉又毁坏了学园的林苑。约公元410年雅典重建了一所柏拉图派学校，529年在查士丁尼治下关闭，但史家认为两者之间没有制度上的延续。色块的终点标的是这所雅典学校的关闭；作为一种哲学，柏拉图主义从未中断。"},"sources":[{"title":"Wikipedia, “Platonic Academy” (summarising Plutarch, Agathias, Cameron and Sorabji)","url":"https://en.wikipedia.org/wiki/Platonic_Academy"}]},
  {"about":"school:stoicism","verdict":"corrected","claim":{"en":"Zeno of Citium was a merchant shipwrecked near Athens.","zh":"季蒂昂的芝诺原是商人，在雅典附近遭遇海难。"},"finding":{"en":"The shipwreck is an ancient anecdote with several versions: Diogenes Laertius reports that Zeno was wrecked carrying purple dye to Piraeus, but also that some say he heard of the wreck while already in Athens, or sold his cargo before turning to philosophy. The atlas now presents it as a story.","zh":"海难是一则有多个版本的古代轶事：第欧根尼·拉尔修记载芝诺运送紫色染料前往比雷埃夫斯途中遇难，但也记载另有说法称他身在雅典时才得知海难，或在转向哲学之前已卖掉货物。本图谱现将其作为传说处理。"},"sources":[{"title":"Diogenes Laertius, Lives of the Eminent Philosophers 7.2–5 (trans. R. D. Hicks, LacusCurtius)","url":"https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Diogenes_Laertius/Lives_of_the_Eminent_Philosophers/7/Zeno*.html"}]},
  {"about":"thinker:heraclitus","verdict":"confirmed","claim":{"en":"“You cannot step into the same river twice” is a later paraphrase of Heraclitus.","zh":"“人不能两次踏进同一条河流”是后人对赫拉克利特的转述。"},"finding":{"en":"The line comes from Plato’s Cratylus (402a). Heraclitus’ authentic river fragment (B12) says something subtler: on those who step into the same rivers, other and other waters flow. He reportedly deposited a single book, probably a collection of sayings, in the temple of Artemis at Ephesus.","zh":"这句话出自柏拉图《克拉底鲁篇》（402a）。赫拉克利特真正的河流残篇（B12）说得更微妙：踏进同一条河流的人，流过他们的水总是不同的。据说他把唯一的一部书（大概是一部格言集）存放在以弗所的阿耳忒弥斯神庙。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Heraclitus”","url":"https://plato.stanford.edu/entries/heraclitus/"}]},
  {"about":"thinker:mulla-sadra","verdict":"corrected","claim":{"en":"Mullā Ṣadrā died in 1640.","zh":"穆拉·萨德拉卒于1640年。"},"finding":{"en":"1640 (1050 AH) is the traditional date, but there is no clear evidence for it. His grandson reported that he died in Basra in 1045 AH (1635–36), on the way to or from the pilgrimage, and two notes in his manuscripts support this, as does the 1635 completion date of his last works. The Asfār, begun in 1606, was completed in Shiraz in 1628.","zh":"1640年（伊斯兰历1050年）只是传统说法，并无确凿证据。他的孙子记载他于伊斯兰历1045年（1635–1636年）卒于巴士拉，两份抄本附注与他最后著作的完成时间（1635年）都支持这一说法。《心灵四旅》始撰于1606年，1628年在设拉子完成。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Mulla Sadra”","url":"https://plato.stanford.edu/entries/mulla-sadra/"}]},
  {"about":"thinker:al-ashari","verdict":"uncertain","claim":{"en":"Al-Ashʿarī wrote the Maqālāt al-Islāmiyyīn about 920 and al-Ibāna about 925.","zh":"艾什尔里约于920年写成《伊斯兰教派言论集》，约于925年写成《宗教原理阐释》。"},"finding":{"en":"Neither book can be dated. The Maqālāt was probably begun in his Muʿtazili years, on the model of al-Balkhī’s book of the same title, and revised later, though al-Dhahabī placed it in his last years. Scholars disagree on whether al-Ibāna came right after his break with the Muʿtazila (c. 912–13) or near the end of his life, and its printed text is suspected of later interpolation. The atlas now gives no year for either.","zh":"两部书都无法确定年代。《言论集》可能始撰于他的穆尔太齐赖派时期，仿照巴尔希的同名著作，后来又有修订；但扎哈比认为它写于晚年。《阐释》是写于他约912–913年脱离穆尔太齐赖派之后不久，还是写于晚年，学界意见不一，其通行刊本还被怀疑有后人窜入。本图谱现不再为两书标注年份。"},"sources":[{"title":"Wikipedia, “Maqalat al-Islamiyyin” (citing Leaman, Netton and al-Dhahabī)","url":"https://en.wikipedia.org/wiki/Maqalat_al-Islamiyyin"}]},
  {"about":"thinker:siger","verdict":"contested","claim":{"en":"Siger wrote the Questions on the Third Book of On the Soul about 1269 and On the Intellective Soul about 1273.","zh":"西格尔约于1269年写《〈论灵魂〉第三卷问题集》，约于1273年写《论理智灵魂》。"},"finding":{"en":"The Questions survive as a student’s report of his lectures, which Van Steenberghen dated to 1269–70, before Aquinas’s On the Unity of the Intellect (1270); it is his most openly Averroist work. On the Intellective Soul is usually placed in 1272–73, after Aquinas’s attack, and moves partly toward Aquinas’s reading. Siger’s own dates are only approximate: born between 1235 and 1240, died between 1281 and 1284.","zh":"《问题集》以学生的听课笔记形式传世，范斯滕伯根将其定在1269–1270年，早于阿奎那1270年的《论理智的统一性》，是他最明显的阿威罗伊主义著作。《论理智灵魂》一般定在1272–1273年，写于阿奎那的批评之后，部分转向了阿奎那的解释。西格尔本人的生卒年也只是约数：生于1235至1240年间，卒于1281至1284年间。"},"sources":[{"title":"Encyclopædia Universalis, “Siger de Brabant”","url":"https://www.universalis.fr/encyclopedie/siger-de-brabant/"},{"title":"Stanford Encyclopedia of Philosophy, “Influence of Arabic and Islamic Philosophy on the Latin West”","url":"https://plato.stanford.edu/entries/arabic-islamic-influence/"}]},
  {"about":"thinker:al-kindi","verdict":"confirmed","claim":{"en":"On First Philosophy dates from about 840.","zh":"《论第一哲学》约成书于840年。"},"finding":{"en":"The treatise is dedicated to the caliph al-Muʿtaṣim (reigned 833–842), under whom al-Kindī’s career peaked, so it can only be placed in those years; 840 is a convenient point within them. Only its first part survives. Al-Kindī was born about 800 and died after 866, probably in the early 870s.","zh":"该书题献给哈里发穆阿台绥姆（833–842年在位），金迪的事业也在其治下达到顶峰，因此只能把它定在这一时期；840年只是其中的一个参考点。该书仅存第一部分。金迪约生于800年，卒于866年之后，大概在870年代初。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Al-Kindi”","url":"https://plato.stanford.edu/entries/al-kindi/"}]},
  {"about":"thinker:saadia","verdict":"confirmed","claim":{"en":"Saadia was born in 882.","zh":"萨阿迪亚生于882年。"},"finding":{"en":"Older works give 892, based on Abraham ibn Daud’s remark that he died at “about fifty”. A Genizah list of his writings compiled by his sons says he died aged sixty less forty days, which gives 882; this date, closer to him in time and place, is now generally accepted. He was born in the Fayyum in Egypt and became gaon of Sura in 928. His Arabic translation of the Torah (the Tafsīr) cannot be dated precisely, so the atlas no longer gives it a year.","zh":"较早的著作多作892年，依据是亚伯拉罕·伊本·达乌德说他去世时“约五十岁”。而一份由他儿子们编写、见于开罗经冢文书（Genizah）的著作目录说他卒年“六十岁差四十天”，由此推得882年；这一来源在时间和地点上都更接近他本人，如今已被普遍接受。他生于埃及法尤姆，928年出任苏拉学院院长（加昂）。他的《托拉》阿拉伯文译注无法确定年代，本图谱不再为其标注年份。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Saadya [Saadiah] Gaon”","url":"https://plato.stanford.edu/entries/saadya/"},{"title":"Wikipedia, “Saadia Gaon” (notes on the birth year)","url":"https://en.wikipedia.org/wiki/Saadia_Gaon"}]},
  {"about":"thinker:boethius","verdict":"contested","claim":{"en":"Boethius lived c. 480–524.","zh":"波爱修约生于480年，卒于524年。"},"finding":{"en":"Reference works differ: the Internet Encyclopedia of Philosophy gives c. 480–524, the Stanford Encyclopedia c. 475–77 to probably 526. All agree that he wrote the Consolation of Philosophy in prison shortly before his execution under Theodoric. His two commentaries on Porphyry’s Isagoge are undated but belong to his translation project, much of which was done by about 518.","zh":"各参考书说法不一：《互联网哲学百科》作约480–524年，《斯坦福哲学百科》作约475–477年至大概526年。各家都同意，《哲学的慰藉》写于他在狄奥多里克治下被处决前的狱中。他对波菲利《导论》的两部注释没有确切年代，属于他的翻译计划，而该计划的大部分在约518年前已经完成。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Anicius Manlius Severinus Boethius”","url":"https://plato.stanford.edu/entries/boethius/"},{"title":"Internet Encyclopedia of Philosophy, “Boethius”","url":"https://iep.utm.edu/boethius/"}]},
  {"about":"thinker:buridan","verdict":"corrected","claim":{"en":"Buridan lived c. 1301–c. 1360.","zh":"布里丹约生于1301年，约卒于1360年。"},"finding":{"en":"He was born around 1300 in or near Béthune in Picardy. He last appears alive in a document of 1358 and was dead by 1361, when one of his benefices passed to someone else. His Summulae and his questions on the Physics went through several lectures and versions and cannot be dated exactly; the edition of the Physics questions follows his “final lecture”. The ass between two haystacks is nowhere in his writings.","zh":"他约1300年生于皮卡第的贝蒂讷或其附近。最后一次以在世身份出现于1358年的文书，1361年他的一份圣俸已转给他人，可知此前已经去世。他的《辩证法纲要》和《物理学》问题集都经过多次讲授和修订，无法确切定年；通行的《物理学》问题集依据的是他的“最后一次讲授”。“两堆干草之间的驴”并不见于他的著作。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “John Buridan”","url":"https://plato.stanford.edu/entries/buridan/"}]},
  {"about":"thinker:ockham","verdict":"confirmed","claim":{"en":"Ockham’s Summa Logicae dates from about 1323 and his Quodlibetal Questions from about 1324.","zh":"奥卡姆的《逻辑大全》约成于1323年，《自由论辩问题集》约成于1324年。"},"finding":{"en":"The Summa Logicae is dated c. 1323–25. The seven Quodlibets record disputations held in London in 1322–24, revised in Avignon in 1324–25. Ockham was born in late 1287 or early 1288 and died in Munich on 9/10 April 1347; he fled Avignon on 26 May 1328 and was excommunicated on 6 June.","zh":"《逻辑大全》约成于1323–1325年。七卷《自由论辩问题集》记录的是他1322–1324年在伦敦主持的论辩，1324–1325年在阿维尼翁修订。奥卡姆生于1287年末或1288年初，1347年4月9日至10日夜卒于慕尼黑；1328年5月26日夜逃离阿维尼翁，6月6日被绝罚。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “William of Ockham”","url":"https://plato.stanford.edu/entries/ockham/"}]},
  {"about":"thinker:rumi","verdict":"confirmed","claim":{"en":"The Dīwān-e Shams dates from about 1250.","zh":"《沙姆斯诗集》约成于1250年。"},"finding":{"en":"It is not a single book written at one time: Rumi composed these ghazals from his meeting with Shams of Tabriz in 1244 and above all after Shams vanished in 1247–48, continuing into the late 1250s. His students collected them after his death; the standard edition by Forūzānfar has about 3,229 ghazals, some of doubtful authenticity. “c. 1250” marks the heart of that period.","zh":"这并不是一次写成的书：鲁米自1244年结识大不里士的沙姆斯起开始创作这些加扎勒，尤其在沙姆斯1247–1248年失踪后大量写作，一直延续到1250年代后期。诗作在他去世后由弟子收集成集；通行的弗鲁赞法尔校订本收约3229首，其中一些真伪存疑。“约1250年”标示的是这一时期的中心。"},"sources":[{"title":"Wikipedia, “Divan-i Shams-i Tabrizi”","url":"https://en.wikipedia.org/wiki/Divan-i_Shams-i_Tabrizi"}]},
  {"about":"school:kalam","verdict":"confirmed","claim":{"en":"Kalām is dated from the 8th century, with Wāṣil ibn ʿAṭāʾ (d. 748).","zh":"凯拉姆从8世纪算起，以瓦绥勒·本·阿塔（卒于748年）为标志。"},"finding":{"en":"This is a convention. Sunni sources trace the Muʿtazila to Wāṣil’s withdrawal from the circle of al-Ḥasan al-Baṣrī in Basra over the status of the grave sinner, but the story of the name is told rather than documented, and the Encyclopaedia of Islam explains the name differently. Arguments about free will and the sinner (the Qadariyya and Murjiʾa) already ran in the late 7th century, so the start date marks when kalām became a recognisable school, not its first debates.","zh":"这只是一种约定。逊尼派史料把穆尔太齐赖派追溯到瓦绥勒在巴士拉因“犯大罪者”的身份问题退出哈桑·巴士里的讲席，但这个得名故事是传说而非实录，《伊斯兰百科全书》对“分离派”一名另有解释。关于自由意志和犯罪者的争论（盖德里派、穆尔吉亚派）在7世纪末就已出现，因此这个起点标示的是凯拉姆成为可辨识学派的时间，而不是最早的争论。"},"sources":[{"title":"Wikipedia, “Muʿtazilism” (citing the Encyclopaedia of Islam)","url":"https://en.wikipedia.org/wiki/Mu%27tazilism"}]},
  {"about":"school:scholasticism","verdict":"corrected","claim":{"en":"Scholasticism ran from c. 1070 to the 16th century, ending with Suárez.","zh":"经院哲学从约1070年延续到16世纪，以苏亚雷斯为终点。"},"finding":{"en":"Suárez died in 1617, and the Stanford Encyclopedia stresses that his death “does not mark the end of this university tradition”: Iberian “baroque” scholasticism continued, and some historians would end medieval Latin philosophy only around 1700. The atlas now ends the block in the early 17th century, after Suárez, and treats later school philosophy as its afterlife.","zh":"苏亚雷斯卒于1617年，《斯坦福哲学百科》特别指出他的去世“并不标志这一大学传统的终结”：伊比利亚的“巴洛克”经院哲学仍在延续，有些史家甚至把中世纪拉丁哲学的下限放在1700年前后。本图谱现在把这一色块的终点改为苏亚雷斯之后的17世纪初，此后的学院哲学视为其余绪。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Medieval Philosophy”","url":"https://plato.stanford.edu/entries/medieval-philosophy/"}]},
  {"about":"school:patristic","verdict":"confirmed","claim":{"en":"Patristic philosophy is drawn as ending around 750, with John of Damascus.","zh":"教父哲学被画到约750年，以大马士革的约翰为终点。"},"finding":{"en":"This is a convention, and a reasonable one: John of Damascus (c. 660–c. 750) is usually counted the last of the Greek Church Fathers. Historians draw the line between late antiquity and medieval philosophy in several places (c. 500, c. 800, or with Augustine himself), so the boundary should be read as a hinge rather than an ending.","zh":"这是一个约定，而且合理：大马士革的约翰（约660–约750年）通常被视为最后一位希腊教父。史家对古代晚期与中世纪哲学的分界说法不一（约500年、约800年，或从奥古斯丁本人算起），因此这条界线应理解为过渡，而非终结。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Medieval Philosophy”","url":"https://plato.stanford.edu/entries/medieval-philosophy/"}]},
  {"about":"link:atomism>kalam","verdict":"contested","claim":{"en":"Kalām atomism echoes Greek atomism.","zh":"凯拉姆的原子论与希腊原子论相呼应。"},"finding":{"en":"Maimonides already traced kalām atomism to the Greeks; 19th-century scholars proposed Indian sources instead. Shlomo Pines found real resemblances but judged the question of origin unresolved, and Alnoor Dhanani compared kalām atoms to Epicurean minimal parts without identifying a route of transmission. Kalām built its arguments from paradoxes of the infinite, in its own way; the link is drawn as a resemblance whose path is unknown, which the note states.","zh":"迈蒙尼德早已把凯拉姆原子论追溯到希腊人；19世纪的学者则提出印度来源说。什洛莫·皮内斯认为两者确有相似，但来源问题无法定论；阿努尔·达纳尼把凯拉姆的原子比作伊壁鸠鲁的“最小部分”，但也未找到传播途径。凯拉姆以自己的方式从无限的悖论出发构建论证；本图谱把这条线作为“来源不明的相似”来画，注释中已说明。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Arabic and Islamic Natural Philosophy and Natural Science”","url":"https://plato.stanford.edu/entries/arabic-islamic-natural/"},{"title":"Iqbal Review (1991), on the sources of kalām atomism","url":"https://iqbalreview.iqbalcyberlibrary.net/app/pdf/1991/1991-10-02.pdf"}]},
  {"about":"thinker:al-ashari","verdict":"confirmed","claim":{"en":"The atlas gives al-Ashʿarī, Saadia and Rumi no teacher ties.","zh":"本图谱没有为艾什尔里、萨阿迪亚和鲁米标出师承关系。"},"finding":{"en":"Their documented teachers are real but fall outside the atlas: al-Ashʿarī studied under the Muʿtazili master al-Jubbāʾī and, by the traditional account, broke with him around his fortieth year; Rumi’s poetry and teaching were transformed by the wandering dervish Shams of Tabriz, to whom the Dīwān is dedicated. The missing ties are a limit of the selection, not a claim that they had no teachers.","zh":"他们确有可考的师承，只是不在本图谱之内：艾什尔里年轻时师从穆尔太齐赖派大师朱巴伊，按传统说法约四十岁时与之决裂；鲁米的诗与教导因游方苦行僧大不里士的沙姆斯而彻底改变，《沙姆斯诗集》即献给此人。缺少这些关系是取材的局限，并不表示他们没有老师。"},"sources":[{"title":"Wikipedia, “Abu al-Hasan al-Ashʿari”","url":"https://en.wikipedia.org/wiki/Abu_al-Hasan_al-Ash%27ari"},{"title":"Wikipedia, “Divan-i Shams-i Tabrizi”","url":"https://en.wikipedia.org/wiki/Divan-i_Shams-i_Tabrizi"}]},
  {"about":"thinker:erasmus","verdict":"contested","claim":{"en":"Erasmus was born c. 1466.","zh":"伊拉斯谟约生于1466年。"},"finding":{"en":"His birth year is genuinely disputed. Erasmus usually reckoned his age as if born in 1466, but the ages he recalled at key events point to 1469, which the Stanford Encyclopedia adopts (28 October 1469). Both years remain in scholarly use.","zh":"他的出生年份确有争议。伊拉斯谟本人多按1466年出生来计算年龄，但他回忆的关键事件发生时的年龄却指向1469年；《斯坦福哲学百科》采用1469年10月28日。两个年份在学界都有人使用。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Desiderius Erasmus”","url":"https://plato.stanford.edu/entries/erasmus/"},{"title":"Wikipedia, “Erasmus” (on the 1466/1469 question)","url":"https://en.wikipedia.org/wiki/Erasmus"}]},
  {"about":"thinker:machiavelli","verdict":"confirmed","claim":{"en":"The Prince is dated 1513 and the Discourses on Livy 1517.","zh":"《君主论》标为1513年，《论李维》标为1517年。"},"finding":{"en":"The Prince was written at the end of 1513 (perhaps early 1514) and printed only in 1532, after his death. The Discourses were begun around 1514–15, finished in 1518–19 and printed in 1531. The atlas gives the years of writing; 1517 stands for the middle of that span.","zh":"《君主论》写于1513年底（或延至1514年初），身后于1532年才付印。《论李维》约始于1514–1515年，1518–1519年完成，1531年出版。本图谱标注的是写作年代，1517年代表其写作期的中段。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Niccolò Machiavelli”","url":"https://plato.stanford.edu/entries/machiavelli/"}]},
  {"about":"thinker:locke","verdict":"confirmed","claim":{"en":"The Essay Concerning Human Understanding and the Two Treatises are dated 1689.","zh":"《人类理解论》与《政府论》标为1689年。"},"finding":{"en":"Both came out in late 1689 (the Essay in December) but carry 1690 on their title pages, so both years appear in references. The English Letter Concerning Toleration also appeared in 1689, after a Latin original printed in Holland the same year.","zh":"两书都在1689年底出版（《人类理解论》在12月），但扉页印的是1690年，因此文献中两个年份并存。英文版《论宗教宽容》也出版于1689年，其拉丁文原版同年在荷兰印行。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “John Locke”","url":"https://plato.stanford.edu/entries/locke/"},{"title":"Wikisource, title page of the 1690 first edition of the Essay","url":"https://en.wikisource.org/wiki/On_the_Human_Understanding"}]},
  {"about":"thinker:mill","verdict":"confirmed","claim":{"en":"Utilitarianism is dated 1861.","zh":"《功利主义》标为1861年。"},"finding":{"en":"It first appeared as three articles in Fraser’s Magazine in October–December 1861 and was published as a book in London in 1863.","zh":"该文最早于1861年10月至12月分三期刊登在《弗雷泽杂志》上，1863年在伦敦出版单行本。"},"sources":[{"title":"Wikipedia, “Utilitarianism (book)”","url":"https://en.wikipedia.org/wiki/Utilitarianism_(book)"},{"title":"Stanford Encyclopedia of Philosophy, “Mill’s Moral and Political Philosophy”","url":"https://plato.stanford.edu/entries/mill-moral-political/"}]},
  {"about":"thinker:diderot","verdict":"confirmed","claim":{"en":"D’Alembert’s Dream is dated 1769.","zh":"《达朗贝尔之梦》标为1769年。"},"finding":{"en":"Diderot wrote the dialogues in 1769. They circulated anonymously in the manuscript newsletter Correspondance littéraire in 1782 and were first published as a book in 1830, long after his death.","zh":"狄德罗于1769年写成这组对话；1782年曾在手抄刊物《文学通讯》上匿名流传，直到1830年才正式出版，那时他已去世多年。"},"sources":[{"title":"Wikipedia, “D’Alembert’s Dream”","url":"https://en.wikipedia.org/wiki/D%27Alembert%27s_Dream"},{"title":"Stanford Encyclopedia of Philosophy, “Denis Diderot”","url":"https://plato.stanford.edu/entries/diderot/"}]},
  {"about":"school:kantianism","verdict":"confirmed","claim":{"en":"Kantianism is drawn until c. 1930, the end of Neo-Kantianism.","zh":"康德主义一直画到约1930年，即新康德主义的终结。"},"finding":{"en":"Neo-Kantianism was the dominant movement in German philosophy from about 1870 until the First World War; its standing collapsed in the decades after 1918, and Hitler’s rise in 1933 nearly erased its institutions. An end around 1930 is a reasonable convention. The other end years in this tradition (rationalism mid-18th century, empiricism 1776, social contract 1790, German idealism 1840s) are likewise cut-offs for the map, not events.","zh":"新康德主义大约从1870年到第一次世界大战一直是德国哲学的主流；1918年后的几十年里声望骤降，1933年希特勒上台几乎抹去了它的机构传承。以约1930年为终点是合理的约定。这一传统中其他学派的终点（理性主义18世纪中叶、经验主义1776年、社会契约论1790年、德国观念论19世纪40年代）同样只是地图上的截止年份，而非具体事件。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Neo-Kantianism”","url":"https://plato.stanford.edu/entries/neo-kantianism/"}]},
  {"about":"tie:descartes>locke","verdict":"confirmed","claim":{"en":"Locke reportedly said Descartes first gave him a relish for philosophy.","zh":"据说洛克曾表示，是笛卡尔最先让他对哲学产生兴趣。"},"finding":{"en":"The report goes back to Lady Damaris Masham, in whose house Locke spent his last years: her memoir of him, sent to Jean Le Clerc, is the source of Le Clerc’s 1705 Éloge and of the first printed lives, which state that the first books that gave Locke a relish for philosophy were those of Descartes. It is second-hand, but early and close.","zh":"这一说法源自洛克晚年寄居其家的达玛丽斯·马沙姆夫人：她寄给让·勒克莱尔的洛克回忆录，是勒克莱尔1705年《洛克先生颂》及最早几部洛克传记的依据，其中说最先让洛克对哲学产生兴趣的书是笛卡尔的著作。这是转述，但出处早且亲近。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Lady Damaris Masham”","url":"https://plato.stanford.edu/entries/lady-masham/"},{"title":"Encyclopaedia Britannica, 3rd ed. (1797), “Locke”","url":"https://jimclifford.ca/early_encyclopedia_britannica/articles/1797/eb_3rd_1797_013025.html"}]},
  {"about":"tie:augustine>descartes","verdict":"contested","claim":{"en":"Descartes drew on Augustine’s “if I am mistaken, I exist”; how far is debated.","zh":"笛卡尔借鉴了奥古斯丁的“如果我受骗，我就存在”；借鉴程度有争议。"},"finding":{"en":"Arnauld’s Fourth Objections (1641) cited Augustine’s On Free Choice 2.3 as a source of the cogito, and in 1640 Colvius pointed Descartes to City of God 11.26; Descartes thanked them but acknowledged no debt and stressed his different use of the argument. Recent scholarship, notably Stephen Menn’s Descartes and Augustine (1998), argues the debt was extensive. The tie is kept as influence, with the dispute stated.","zh":"阿尔诺在《第四组反驳》（1641）中指出，“我思”的来源之一是奥古斯丁《论自由意志》2.3；1640年科尔维乌斯也提醒笛卡尔注意《上帝之城》11.26。笛卡尔表示感谢，却不承认受惠，并强调自己对这一论证的用法不同。近来的研究，尤其是梅恩的《笛卡尔与奥古斯丁》（1998），认为他受惠甚多。本图谱保留这条影响关系，并注明争议。"},"sources":[{"title":"The Cambridge Descartes Lexicon, “Augustine, Aurelius”","url":"https://www.cambridge.org/core/books/cambridge-descartes-lexicon/augustine-aurelius-354430/82B4B23FDBCCCBF3F816C086817C94A8"}]},
  {"about":"school:rationalism","verdict":"confirmed","claim":{"en":"The school links to the Wikipedia article “Rationalism”.","zh":"该学派链接到维基百科条目“Rationalism”。"},"finding":{"en":"English Wikipedia has no separate article on Continental rationalism: the title “Continental rationalism” redirects to “Rationalism”, which covers Descartes, Spinoza and Leibniz along with rationalism in general. The link stands.","zh":"英文维基百科没有单独的“欧陆理性主义”条目：“Continental rationalism”会重定向到“Rationalism”，该条目在介绍一般理性主义的同时也涵盖笛卡尔、斯宾诺莎与莱布尼茨。链接保持不变。"},"sources":[{"title":"Wikipedia, “Continental rationalism” (redirect to “Rationalism”)","url":"https://en.wikipedia.org/wiki/Continental_rationalism"}]},
  {"about":"link:empiricism>utilitarianism","verdict":"confirmed","claim":{"en":"Bentham wrote that reading Hume made him feel “as if scales had fallen from my eyes”.","zh":"边沁写道，读休谟时他“仿佛眼睛上的鳞片掉了下来”。"},"finding":{"en":"In a footnote to A Fragment on Government (1776) Bentham says that the third volume of Hume’s Treatise demonstrates that the foundations of all virtue lie in utility, and that on reading it he “felt as if scales had fallen from my eyes”.","zh":"边沁在《政府片论》（1776）的一条脚注中说，休谟《人性论》第三卷证明了一切美德的基础在于效用，读到这一部分时他“仿佛眼睛上的鳞片掉了下来”。"},"sources":[{"title":"Bentham, A Fragment on Government (1776), Early Modern Texts edition","url":"https://www.earlymoderntexts.com/assets/pdfs/bentham1776.pdf"}]},
  {"about":"tie:hegel>schopenhauer","verdict":"confirmed","claim":{"en":"Schopenhauer scheduled his Berlin lectures at the same hour as Hegel’s.","zh":"叔本华把自己在柏林的课排在与黑格尔相同的时段。"},"finding":{"en":"In March 1820 Schopenhauer, newly licensed to teach in Berlin, scheduled his class at the same time as Hegel’s popular lectures; few students came. He had studied in Berlin in 1811–13, where his lecturers included Fichte.","zh":"1820年3月，刚获得柏林大学授课资格的叔本华把课排在黑格尔大受欢迎的讲座同一时段，结果几乎没有学生来听。他在1811–1813年曾就读于柏林，老师中包括费希特。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Arthur Schopenhauer”","url":"https://plato.stanford.edu/entries/schopenhauer/"}]},
  {"about":"thinker:habermas","verdict":"corrected","claim":{"en":"Jürgen Habermas is listed as living (born 1929).","zh":"图谱把尤尔根·哈贝马斯列为在世（生于1929年）。"},"finding":{"en":"Habermas died on 14 March 2026, aged 96. Goethe University Frankfurt and his publisher Suhrkamp held a memorial symposium for him on 19 June 2026.","zh":"哈贝马斯于2026年3月14日去世，享年96岁。2026年6月19日，法兰克福歌德大学与他的出版社苏尔坎普为他举办了纪念研讨会。"},"sources":[{"title":"Daily Nous, “Jürgen Habermas (1929–2026)”, 14 March 2026","url":"https://dailynous.com/2026/03/14/jurgen-habermas-1929-2026/"},{"title":"Holberg Prize, “In Memoriam: Jürgen Habermas (1929–2026)”","url":"https://holbergprize.org/news/in-memoriam-jurgen-habermas/"},{"title":"Goethe University Frankfurt, press release on the memorial symposium (2026)","url":"https://www.uni-frankfurt.de/en/newsroom/meldungen/pressemitteilungen/2026/die-kritische-theorie-nach-habermas"}]},
  {"about":"tie:merleau-ponty>fanon","verdict":"uncertain","claim":{"en":"Fanon attended Merleau-Ponty’s lectures while studying in Lyon.","zh":"法农在里昂求学期间听过梅洛-庞蒂的课。"},"finding":{"en":"The dates fit: Fanon studied medicine in Lyon after the war, and Merleau-Ponty taught psychology at the University of Lyon from 1945 to 1949. That Fanon sat in on his lectures is repeated in biographies and reference works, but the encyclopedia entries we checked do not confirm it; what is certain is that Black Skin, White Masks draws on Merleau-Ponty’s phenomenology of the body.","zh":"时间上吻合：法农战后在里昂学医，梅洛-庞蒂1945至1949年在里昂大学讲授心理学。法农旁听过他的课，这一说法见于传记与参考书，但我们核查的百科条目并未证实；可以确定的是，《黑皮肤，白面具》借用了梅洛-庞蒂的身体现象学。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Maurice Merleau-Ponty” (Lyon appointments 1945–1949)","url":"https://plato.stanford.edu/entries/merleau-ponty/"},{"title":"Stanford Encyclopedia of Philosophy, “Frantz Fanon”","url":"https://plato.stanford.edu/entries/frantz-fanon/"},{"title":"Wikipedia, “Frantz Fanon” (Lyon studies; claim uncited)","url":"https://en.wikipedia.org/wiki/Frantz_Fanon"}]},
  {"about":"tie:husserl>heidegger","verdict":"confirmed","claim":{"en":"Husserl’s link to Heidegger is coded as influence, not teaching: Heidegger was his assistant, not his doctoral student.","zh":"胡塞尔与海德格尔的关系被标为“影响”而非“师承”：海德格尔是他的助手，而不是他的博士生。"},"finding":{"en":"Heidegger took his doctorate in 1913 and wrote his habilitation (1915) under the Neo-Kantian Heinrich Rickert. He became Husserl’s assistant in Freiburg in 1919 and they ran seminars together; he later dedicated Being and Time to Husserl “in friendship and admiration”. “Influence” is the accurate kind.","zh":"海德格尔于1913年获得博士学位，1915年的教授资格论文由新康德主义者李凯尔特指导。1919年他成为胡塞尔在弗莱堡的助手，两人合开研讨课；后来他把《存在与时间》献给胡塞尔，“谨致友谊与敬意”。标为“影响”是准确的。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Martin Heidegger”","url":"https://plato.stanford.edu/entries/heidegger/"}]},
  {"about":"tie:beauvoir>sartre","verdict":"contested","claim":{"en":"Beauvoir influenced Sartre’s philosophy.","zh":"波伏瓦影响了萨特的哲学。"},"finding":{"en":"How far is debated. Beauvoir herself called her philosophy an elaboration of Sartre’s, but since the 1990s scholars have asked whether ideas in Being and Nothingness (1943) first appeared in her novel She Came to Stay (1943); her diaries show ideas developed before, alongside and often against his.","zh":"影响有多大，学界有争论。波伏瓦本人称自己的哲学只是对萨特哲学的阐发；但自20世纪90年代起，学者们追问《存在与虚无》（1943）中的一些思想是否先出现在她的小说《女宾》（1943）里；她的日记表明，她的思想在萨特之前、与他并行、也常常与他相左地发展。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Simone de Beauvoir”","url":"https://plato.stanford.edu/entries/beauvoir/"}]},
  {"about":"school:existentialism","verdict":"confirmed","claim":{"en":"Existentialism is drawn from 1843 to 1980: forerunners in the 1840s, a heyday in the 1940s–1960s.","zh":"存在主义的时间跨度画作1843年至1980年：19世纪40年代有先驱，20世纪40至60年代为鼎盛期。"},"finding":{"en":"These bounds are a convention, as the label is open-ended: the word was introduced by Gabriel Marcel in 1943, Kierkegaard and Nietzsche are its acknowledged forerunners, and it peaked in post-war France. 1843 is Kierkegaard’s Either/Or and 1980 the death of Sartre; the movement still has academic heirs.","zh":"这一时间界限是约定俗成的，因为这个标签本身边界模糊：“存在主义”一词由马塞尔在1943年提出，克尔凯郭尔和尼采是公认的先驱，其鼎盛期在战后法国。1843年是克尔凯郭尔《非此即彼》出版之年，1980年是萨特去世之年；这一思潮至今仍有学术传人。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Existentialism”","url":"https://plato.stanford.edu/entries/existentialism/"}]},
  {"about":"school:hermeneutics","verdict":"confirmed","claim":{"en":"Hermeneutics as a school is dated from 1805, Schleiermacher’s first lectures on it.","zh":"作为学派的诠释学从1805年算起，即施莱尔马赫首次讲授诠释学之年。"},"finding":{"en":"Schleiermacher first lectured on hermeneutics in 1805, while teaching at Halle, and gave the course repeatedly until 1833; his lecture notes were published after his death, in 1838.","zh":"施莱尔马赫于1805年在哈雷任教时首次讲授诠释学，此后反复开设这门课直到1833年；他的讲稿在他去世后于1838年出版。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Friedrich Daniel Ernst Schleiermacher”","url":"https://plato.stanford.edu/entries/schleiermacher/"}]},
  {"about":"school:structuralism","verdict":"confirmed","claim":{"en":"Structuralism is drawn from 1916 to 1980.","zh":"结构主义的时间跨度画作1916年至1980年。"},"finding":{"en":"A convention: 1916 is the publication of Saussure’s Course in General Linguistics; structuralism rose in France after the war with Lévi-Strauss (1949) and peaked in the 1960s; by the late 1960s its tenets were attacked by the post-structuralists, and 1980 marks Barthes’s death.","zh":"这是约定俗成的界限：1916年是索绪尔《普通语言学教程》出版之年；战后结构主义随列维-斯特劳斯（1949）在法国兴起，在20世纪60年代达到鼎盛；60年代末，其基本信条遭到后结构主义者的攻击；1980年是巴特去世之年。"},"sources":[{"title":"Wikipedia, “Structuralism”","url":"https://en.wikipedia.org/wiki/Structuralism"}]},
  {"about":"thinker:benjamin","verdict":"confirmed","claim":{"en":"Benjamin’s “The Work of Art in the Age of Mechanical Reproduction” is dated 1935.","zh":"本雅明《机械复制时代的艺术作品》标为1935年。"},"finding":{"en":"1935 is when he wrote it in Paris exile; he reworked it between December 1935 and February 1936, and it was first published in 1936, in a French translation by Pierre Klossowski in the Zeitschrift für Sozialforschung. Later German versions followed until 1939.","zh":"1935年是他在巴黎流亡中写作此文之年；1935年12月至1936年2月间他改写了全文，1936年首次发表，是克洛索夫斯基的法译本，刊于《社会研究杂志》。此后直到1939年还有几个德文版本。"},"sources":[{"title":"Wikipedia, “The Work of Art in the Age of Mechanical Reproduction”","url":"https://en.wikipedia.org/wiki/The_Work_of_Art_in_the_Age_of_Mechanical_Reproduction"},{"title":"Stanford Encyclopedia of Philosophy, “Walter Benjamin”","url":"https://plato.stanford.edu/entries/benjamin/"}]},
  {"about":"thinker:spivak","verdict":"confirmed","claim":{"en":"Spivak’s “Can the Subaltern Speak?” is dated 1988.","zh":"斯皮瓦克《底层人能说话吗？》标为1988年。"},"finding":{"en":"The standard text appeared in 1988 in Cary Nelson and Lawrence Grossberg (eds.), Marxism and the Interpretation of Culture (pp. 271–313). It is reported to have grown out of a 1983 talk, and Spivak revised it again in A Critique of Postcolonial Reason (1999).","zh":"通行文本于1988年收入纳尔逊与格罗斯伯格主编的《马克思主义与文化阐释》（第271–313页）。据称它源自1983年的一次演讲；斯皮瓦克后来又在《后殖民理性批判》（1999）中修订了它。"},"sources":[{"title":"Oxford University Press Learning Link, “Key Thinker: Gayatri Chakravorty Spivak”","url":"https://learninglink.oup.com/access/content/ramgotra-choat1e-resources/ramgotra-choat1e-key-thinker-gayatri-chakravorty-spivak"},{"title":"Wikipedia, “Can the Subaltern Speak?”","url":"https://en.wikipedia.org/wiki/Can_the_Subaltern_Speak%3F"}]},
  {"about":"thinker:gramsci","verdict":"confirmed","claim":{"en":"Gramsci’s Prison Notebooks are dated 1935.","zh":"葛兰西《狱中札记》标为1935年。"},"finding":{"en":"The atlas dates them by the end of writing: Gramsci filled the notebooks between 1929 and 1935. They were first published by Einaudi in a thematic selection in 1948–51, and in Valentino Gerratana’s complete critical edition in 1975, now the standard text.","zh":"图谱以写作完成之年标注：葛兰西在1929至1935年间写下这些札记。埃伊纳乌迪出版社于1948–1951年首次按主题分卷出版，1975年又出版了杰拉塔纳编的完整校勘本，这是今天的标准版本。"},"sources":[{"title":"Wikipedia, “Prison Notebooks”","url":"https://en.wikipedia.org/wiki/Prison_Notebooks"},{"title":"International Gramsci Society, Concordance table of the Prison Notebooks","url":"https://www.internationalgramscisociety.org/resources/concordance_table/index.html"}]},
  {"about":"thinker:engels","verdict":"confirmed","claim":{"en":"Engels is described as a manufacturer’s son.","zh":"恩格斯被称为“工厂主之子”。"},"finding":{"en":"His father, Friedrich Engels Sr., was a prosperous cotton-mill owner in Barmen who co-founded the firm Ermen & Engels in 1837, later with a thread factory in Manchester. Engels worked for the firm in Manchester from 1842 and again from 1850, became a partner in 1864 and retired in 1869.","zh":"他的父亲老弗里德里希·恩格斯是巴门一位富裕的棉纺厂主，1837年与人合伙创办欧门-恩格斯公司，后来在曼彻斯特开设了纱线厂。恩格斯从1842年起、又从1850年起在公司的曼彻斯特分部工作，1864年成为合伙人，1869年退休。"},"sources":[{"title":"Wikipedia, “Friedrich Engels”","url":"https://en.wikipedia.org/wiki/Friedrich_Engels"}]},
  {"about":"thinker:searle","verdict":"corrected","claim":{"en":"The atlas listed John Searle as living (born 1932).","zh":"图谱原将约翰·塞尔列为在世（1932年生）。"},"finding":{"en":"Searle died in September 2025, aged 93, in Safety Harbor, Florida. The New York Times obituary (as reported by the Boston Globe) gives 16 September; Philosophy Now gives 17 September.","zh":"塞尔于2025年9月在佛罗里达州安全港去世，享年93岁。《纽约时报》讣告（据《波士顿环球报》转述）记为9月16日，《现在的哲学》（Philosophy Now）记为9月17日。"},"sources":[{"title":"Boston Globe, “John Searle, philosopher who wrestled with AI, dies at 93” (2025)","url":"https://www.bostonglobe.com/2025/10/13/metro/john-searle-philosopher-ai-obituary"},{"title":"Philosophy Now, “John Searle 1932–2025”","url":"https://philosophynow.org/issues/171/John_Searle_1932-2025"}]},
  {"about":"thinker:macintyre","verdict":"confirmed","claim":{"en":"Alasdair MacIntyre died in 2025.","zh":"阿拉斯戴尔·麦金太尔于2025年去世。"},"finding":{"en":"MacIntyre died on 21 May 2025, aged 96; the University of Notre Dame’s de Nicola Center announced his death on 23 May. He was born in Glasgow on 12 January 1929.","zh":"麦金太尔于2025年5月21日去世，享年96岁；圣母大学德尼科拉中心于5月23日宣布了这一消息。他1929年1月12日生于格拉斯哥。"},"sources":[{"title":"Today’s Catholic (OSV News), “Alasdair MacIntyre, ND professor, Catholic philosopher, dies at 96” (29 May 2025)","url":"https://todayscatholic.org/alasdair-macintyre-nd-professor-catholic-philosopher-dies-at-96/"}]},
  {"about":"thinker:dennett","verdict":"confirmed","claim":{"en":"Daniel Dennett died in 2024.","zh":"丹尼尔·丹尼特于2024年去世。"},"finding":{"en":"Dennett died on 19 April 2024, aged 82, as reported in the New York Times obituary cited by the National Center for Science Education.","zh":"丹尼特于2024年4月19日去世，享年82岁，见美国国家科学教育中心援引的《纽约时报》讣告。"},"sources":[{"title":"NCSE, “Daniel C. Dennett, philosopher and evolution enthusiast, dies at 82”","url":"https://ncse.ngo/daniel-c-dennett-philosopher-and-evolution-enthusiast-dies-82"},{"title":"Philosophy Now, “Daniel C. Dennett 1942–2024”","url":"https://philosophynow.org/issues/162/Daniel_C_Dennett_1942-2024"}]},
  {"about":"thinker:nagel","verdict":"confirmed","claim":{"en":"Thomas Nagel is living; he studied at Oxford as well as Harvard, and Rawls supervised his doctorate.","zh":"托马斯·内格尔在世；他曾在牛津和哈佛求学，博士导师是罗尔斯。"},"finding":{"en":"Nagel, born in Belgrade on 4 July 1937, took a BA at Cornell (1958), a BPhil at Corpus Christi College, Oxford (1960), and a Harvard PhD (1963) supervised by John Rawls. No report of his death was found as of October 2026. His Oxford years overlapped with Austin’s, but no teaching relationship is documented, so no tie is drawn.","zh":"内格尔1937年7月4日生于贝尔格莱德，1958年获康奈尔学士，1960年获牛津基督圣体学院哲学学士（BPhil），1963年获哈佛博士，导师为罗尔斯。截至2026年10月未见其去世的报道。他在牛津的时期与奥斯汀重叠，但没有师生关系的记载，因此不画连线。"},"sources":[{"title":"Wikipedia, “Thomas Nagel”","url":"https://en.wikipedia.org/wiki/Thomas_Nagel"}]},
  {"about":"thinker:singer","verdict":"confirmed","claim":{"en":"Peter Singer is living.","zh":"彼得·辛格在世。"},"finding":{"en":"Singer is Emeritus Professor of Bioethics at Princeton and was still publishing columns in October 2026. A report of his death that circulated in July 2026 was a hoax.","zh":"辛格是普林斯顿大学生命伦理学荣休教授，2026年10月仍在发表专栏文章。2026年7月流传的死讯是谣言。"},"sources":[{"title":"Project Syndicate, columnist page: Peter Singer","url":"https://www1.project-syndicate.org/columnist/peter-singer"},{"title":"Wikipedia, “Peter Singer”","url":"https://en.wikipedia.org/wiki/Peter_Singer"}]},
  {"about":"thinker:nussbaum","verdict":"confirmed","claim":{"en":"Martha Nussbaum is living and teaches at Chicago.","zh":"玛莎·努斯鲍姆在世，任教于芝加哥大学。"},"finding":{"en":"Nussbaum is Ernst Freund Distinguished Service Professor of Law and Ethics at the University of Chicago, and in September 2026 the Library of Congress named her winner of the 2026 Kluge Prize.","zh":"努斯鲍姆是芝加哥大学恩斯特·弗罗因德法律与伦理学杰出服务教授；2026年9月，美国国会图书馆宣布她获得2026年克鲁格奖。"},"sources":[{"title":"University of Chicago Law School, faculty page: Martha C. Nussbaum","url":"https://law.uchicago.edu/faculty/nussbaum"},{"title":"Daily Nous, “Nussbaum Wins Kluge Prize”","url":"https://dailynous.com/nussbaum-wins-kluge-prize/"}]},
  {"about":"thinker:chalmers","verdict":"confirmed","claim":{"en":"David Chalmers is living and teaches at NYU.","zh":"大卫·查默斯在世，任教于纽约大学。"},"finding":{"en":"Chalmers, born 20 April 1966, is University Professor of Philosophy and Neural Science at New York University and co-director of its Center for Mind, Brain, and Consciousness; he took his PhD at Indiana University in 1993.","zh":"查默斯生于1966年4月20日，现任纽约大学哲学与神经科学校级教授、心灵脑与意识中心联合主任；1993年获印第安纳大学博士学位。"},"sources":[{"title":"David Chalmers, curriculum vitae","url":"https://consc.net/cv/"}]},
  {"about":"thinker:chalmers","verdict":"corrected","claim":{"en":"The atlas gave the Chinese title of Reality+ as 《现实+》, a working translation.","zh":"图谱原将《Reality+》的中文书名写作《现实+》，系暂译。"},"finding":{"en":"A Chinese edition exists: 《现实+：每个虚拟世界都是一个新的现实》, translated by Xiong Xiang (熊祥) and published by CITIC Press (见识城邦) in December 2022.","zh":"该书已有中译本：《现实+：每个虚拟世界都是一个新的现实》，熊祥译，中信出版集团·见识城邦2022年12月出版。"},"sources":[{"title":"The Paper (澎湃新闻), excerpt with publication details of 《现实+》","url":"https://www.thepaper.cn/newsDetail_forward_22323971"}]},
  {"about":"thinker:ayer","verdict":"uncertain","claim":{"en":"The Chinese title of Ayer’s The Problem of Knowledge (1956) is given as 《知识问题》.","zh":"艾耶尔《The Problem of Knowledge》（1956）的中文书名写作《知识问题》。"},"finding":{"en":"The book is Ayer’s 1956 study of scepticism, perception, memory and other minds. No published Chinese translation could be found, so 《知识问题》 remains a descriptive rendering of the title, not the name of an edition.","zh":"该书是艾耶尔1956年关于怀疑论、知觉、记忆与他心问题的著作。未能查到已出版的中译本，因此《知识问题》只是对书名的直译，并非某个中文版的书名。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Alfred Jules Ayer”","url":"https://plato.stanford.edu/entries/ayer/"}]},
  {"about":"thinker:ryle","verdict":"uncertain","claim":{"en":"The Chinese title of Ryle’s Dilemmas (1954) is given as 《两难》.","zh":"赖尔《Dilemmas》（1954）的中文书名写作《两难》。"},"finding":{"en":"Dilemmas collects Ryle’s Tarner Lectures on apparent conflicts between theories. No published Chinese translation could be found, so 《两难》 remains a descriptive rendering of the title.","zh":"《Dilemmas》收录赖尔讨论理论之间表面冲突的塔纳讲座。未能查到已出版的中译本，因此《两难》只是对书名的直译。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Gilbert Ryle”","url":"https://plato.stanford.edu/entries/ryle/"}]},
  {"about":"tie:carnap>quine","verdict":"confirmed","claim":{"en":"Carnap both shaped Quine and was the main target of his critique, so the atlas draws two ties between them.","zh":"卡尔纳普既塑造了奎因，又是奎因批判的主要对象，因此图谱在两人之间画了两条关系。"},"finding":{"en":"Quine’s 1932–33 fellowship took him to Prague, where Carnap was teaching; the Stanford Encyclopedia names the Logical Empiricists, “especially Carnap”, as Quine’s strongest influence, and reads “Two Dogmas of Empiricism” (1951) as largely a debate with Carnap. Both ties stand.","zh":"奎因1932–33年游学期间到过卡尔纳普任教的布拉格；《斯坦福哲学百科》称逻辑经验主义者、“尤其是卡尔纳普”对奎因影响最大，并认为《经验论的两个教条》（1951）在很大程度上是同卡尔纳普的辩论。两条关系都成立。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Willard Van Orman Quine”","url":"https://plato.stanford.edu/entries/quine/"}]},
  {"about":"tie:peirce>dewey","verdict":"confirmed","claim":{"en":"Dewey took Peirce’s logic course at Johns Hopkins; the atlas records this as influence rather than teaching.","zh":"杜威在约翰斯·霍普金斯大学上过皮尔士的逻辑课；图谱将其记为“影响”而非“师承”。"},"finding":{"en":"As a graduate student at Johns Hopkins (1882–84) Dewey studied logic with Peirce but found it “too mathematical” and did not pursue it; Peirce had no sizable impact on him then, though Dewey later credited Peirce’s pragmatism as an important influence. “Influenced” is the right kind of tie.","zh":"杜威1882–84年在约翰斯·霍普金斯读研究生时跟皮尔士学过逻辑，但觉得“太数学化”而没有继续；当时皮尔士对他影响不大，杜威后来却承认皮尔士的实用主义对他影响重要。因此记为“影响”是恰当的。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “John Dewey”","url":"https://plato.stanford.edu/entries/dewey/"}]},
  {"about":"tie:ryle>ayer","verdict":"confirmed","claim":{"en":"Ryle was Ayer’s tutor at Christ Church and suggested he go to Vienna in 1933.","zh":"赖尔是艾耶尔在基督教堂学院的导师，并建议他于1933年去维也纳。"},"finding":{"en":"Ryle was one of Ayer’s tutors at Christ Church, Oxford; having met Schlick in 1930, he encouraged Ayer to attend the Vienna Circle, which Ayer did from January to March 1933.","zh":"赖尔是艾耶尔在牛津基督教堂学院的导师之一；他1930年结识石里克，鼓励艾耶尔去参加维也纳学派的聚会，艾耶尔于1933年1月至3月前往。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Alfred Jules Ayer”","url":"https://plato.stanford.edu/entries/ayer/"}]},
  {"about":"tie:moore>russell","verdict":"corrected","claim":{"en":"The note quoted Russell as following Moore’s rebellion against idealism “with a sense of emancipation”.","zh":"原注释引用罗素的话，说他“怀着解放感”追随摩尔反叛唯心论。"},"finding":{"en":"That wording could not be found in Russell’s writings. His account in My Philosophical Development dates the revolt against Kant and Hegel to late 1898: “Moore led the way, but I followed closely in his footsteps.” The note now quotes this.","zh":"罗素著作中查不到这一措辞。他在《我的哲学发展》中把反叛康德与黑格尔的时间定在1898年底：“摩尔带路，而我紧随其后。”注释已改为引用这句话。"},"sources":[{"title":"Richard L. Cartwright, “Russell and Moore, 1898–1905”, in The Cambridge Companion to Bertrand Russell (2003)","url":"https://www.cambridge.org/core/books/cambridge-companion-to-bertrand-russell/russell-and-moore-18981905/03425ABC51AB7AB1EAC9FBC58217EAEE"}]},
  {"about":"tie:kant>peirce","verdict":"corrected","claim":{"en":"The note said Peirce studied the Critique of Pure Reason for hours every day for more than three years.","zh":"原注释说皮尔士曾连续三年多每天花数小时研读《纯粹理性批判》。"},"finding":{"en":"The Stanford Encyclopedia confirms that Peirce began Kant in 1855, his first year at Harvard, spent about three years in intense study of the Critique, and kept rereading it all his life, though he came to judge its logic flawed. The exact daily-hours wording could not be checked in a source, so the note now states what is documented.","zh":"《斯坦福哲学百科》证实：皮尔士1855年在哈佛一年级时开始读康德，对《纯粹理性批判》下了约三年苦功，此后终生反复研读，尽管他后来认为其逻辑有缺陷。“每天数小时”的说法未能在来源中核实，因此注释改为只陈述有据可查的内容。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Charles Sanders Peirce”","url":"https://plato.stanford.edu/entries/peirce/"}]},
  {"about":"school:post-positivism","verdict":"confirmed","claim":{"en":"The school’s “read more” link points to the Wikipedia article “Postpositivism”.","zh":"该学派的“延伸阅读”链接指向维基百科“后实证主义”条目。"},"finding":{"en":"The article covers the critique of positivism in philosophy of science and the social sciences, and its history section discusses Popper’s falsificationism and Kuhn’s paradigms; Quine is mentioned only in passing. It is the closest general article and is kept.","zh":"该条目讨论科学哲学与社会科学中对实证主义的批判，历史部分介绍了波普尔的证伪主义和库恩的范式；奎因只是顺带提及。它是最接近的综合条目，予以保留。"},"sources":[{"title":"Wikipedia, “Postpositivism”","url":"https://en.wikipedia.org/wiki/Postpositivism"}]},
  {"about":"school:liberal-egalitarianism","verdict":"confirmed","claim":{"en":"The school links to the article on A Theory of Justice because there is no dedicated article.","zh":"该学派链接到《正义论》条目，因为没有专门条目。"},"finding":{"en":"English Wikipedia has no article titled “Liberal egalitarianism” (the page returns 404); Rawls’s A Theory of Justice is the founding text of the debate, so the link is kept.","zh":"英文维基百科没有题为“Liberal egalitarianism”的条目（页面不存在）；罗尔斯的《正义论》是这场讨论的奠基文本，因此保留该链接。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Egalitarianism”","url":"https://plato.stanford.edu/archives/sum2025/entries/egalitarianism/"}]},
  {"about":"thinker:buddha","verdict":"contested","claim":{"en":"The Buddha lived c. 480–400 BCE; the traditional dating is 563–483 BCE.","zh":"佛陀生活于约公元前480–前400年；传统说法为前563–前483年。"},"finding":{"en":"The Stanford Encyclopedia notes that his dates were long put at about 560–480 BCE, but that many scholars now hold he died around 405 BCE. The 563–483 range is an older scholarly reckoning rather than a Buddhist tradition (the Theravāda reckoning is earlier still), so the atlas now calls it the older dating.","zh":"《斯坦福哲学百科》指出，佛陀的年代长期被定为约公元前560–前480年，但如今许多学者认为他卒于约前405年。前563–前483年是较早的学界推算，并非佛教传统本身的说法（上座部的纪年还要更早），因此本图谱改称其为“较早的说法”。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Buddha”","url":"https://plato.stanford.edu/entries/buddha/"}]},
  {"about":"thinker:mahavira","verdict":"contested","claim":{"en":"Mahāvīra lived traditionally 599–527 BCE, though many scholars date him later.","zh":"大雄的传统生卒年为公元前599–前527年，但许多学者定得更晚。"},"finding":{"en":"Jain tradition gives his birth as 599 BCE and his death as 527 BCE (Śvetāmbara) or 510 BCE (Digambara). Modern historians tie his dates to the Buddha’s: Paul Dundas places his death around 425 BCE or a few years after, and Jeffery D. Long gives c. 499–427 BCE. The atlas keeps the traditional dates on the map and says that scholars date him later.","zh":"耆那教传统认为他生于公元前599年，卒于前527年（白衣派）或前510年（天衣派）。现代史家把他的年代与佛陀的年代联系起来：保罗·邓达斯认为他约卒于前425年或稍后，杰弗里·朗给出约前499–前427年。本图谱在图上沿用传统年代，并注明学界多定得更晚。"},"sources":[{"title":"Wikipedia, “Mahavira” (citing Dundas and Long)","url":"https://en.wikipedia.org/wiki/Mahavira"},{"title":"Internet Encyclopedia of Philosophy, “Jain Philosophy”","url":"https://iep.utm.edu/jain/"}]},
  {"about":"thinker:umasvati","verdict":"contested","claim":{"en":"Umāsvāti lived sometime in the 2nd–5th century CE; plotted at c. 350–420.","zh":"乌玛斯瓦蒂生活于公元2至5世纪之间；图上放在约350–420年。"},"finding":{"en":"Scholars disagree: Padmanabh Jaini places him around the 2nd century, Paul Dundas dates him and the Tattvārtha Sūtra to the 4th–5th century, and Walter Slaje notes doubts even about whether Umāsvāti and Umāsvāmī were one person. The claim that both main sects accept his text is confirmed: it is studied in all four Jain traditions, and both Śvetāmbaras and Digambaras claim him.","zh":"学者意见不一：帕德马纳布·贾伊尼认为他约在2世纪，保罗·邓达斯把他和《谛义证得经》定在4至5世纪，瓦尔特·斯拉耶则指出，就连乌玛斯瓦蒂与乌玛斯瓦米是否为同一人都有疑问。“两大派都接受此书”这一说法得到证实：四个耆那教传统都研习它，白衣派与天衣派也都认他为本派人物。"},"sources":[{"title":"Wikipedia, “Umaswati” (citing Jaini, Dundas, Slaje)","url":"https://en.wikipedia.org/wiki/Umaswati"}]},
  {"about":"thinker:kanada","verdict":"contested","claim":{"en":"The Vaiśeṣika Sūtra is dated c. 150 BCE.","zh":"《胜论经》约成书于公元前150年。"},"finding":{"en":"Kaṇāda’s century is unknown; estimates run from the 6th to the 2nd century BCE, with some scholars arguing for an early date because the Sūtra never mentions Buddhism. Matilal and Fowler place the text’s systematisation between 200 BCE and the start of the common era, which the atlas’s c. 150 BCE falls within; its doctrines may be older.","zh":"迦那陀生活在哪个世纪并无定论，推定从公元前6世纪到前2世纪不等；有学者因为《胜论经》从未提及佛教而主张较早的年代。马蒂拉尔与福勒认为此经在公元前200年至公元纪元开始之间定型，本图谱所取的约前150年在此范围内；其学说本身可能更古老。"},"sources":[{"title":"Wikipedia, “Kaṇāda” (citing Matilal 1977, Fowler 2002, Riepe 1961)","url":"https://en.wikipedia.org/wiki/Ka%E1%B9%87%C4%81da"}]},
  {"about":"thinker:akshapada","verdict":"confirmed","claim":{"en":"Akṣapāda Gautama, traditional author of the Nyāya Sūtra, is dated somewhere between the 2nd century BCE and the 2nd century CE.","zh":"《正理经》的传统作者足目（乔达摩）年代在公元前2世纪至公元2世纪之间。"},"finding":{"en":"The Internet Encyclopedia of Philosophy calls the Nyāya-sūtra the oldest extant Nyāya text and dates its attributed author Gautama to c. 200 CE, at the late end of the atlas’s range. Wikipedia has no separate article on him: “Akshapada Gautama” redirects to “Nyāya Sūtras”, so the link now points there directly.","zh":"《互联网哲学百科》称《正理经》为现存最古老的正理派文献，并把托名作者乔达摩定在约公元200年，处于本图谱所给范围的晚端。维基百科没有他的独立条目，“Akshapada Gautama”会重定向到“Nyāya Sūtras”，因此链接现在直接指向后者。"},"sources":[{"title":"Internet Encyclopedia of Philosophy, “Nyāya”","url":"https://iep.utm.edu/nyaya/"}]},
  {"about":"thinker:patanjali","verdict":"contested","claim":{"en":"Patañjali compiled the Yoga Sūtra, c. 4th–5th century CE (dating disputed).","zh":"帕坦伽利编纂《瑜伽经》，约公元4至5世纪（年代有争议）。"},"finding":{"en":"Estimates for the Yoga Sūtra run from 500 BCE to 450 CE, but later dates are more widely accepted; Philipp Maas places the Pātañjalayogaśāstra at about 400 CE. The older view that he was the grammarian Patañjali (2nd century BCE) is rejected by most scholars: no text before Bhoja (11th century) conflates the two.","zh":"《瑜伽经》的年代推定从公元前500年到公元450年不等，但较晚的年代更为学界所接受；菲利普·马斯把《帕坦伽利瑜伽论》定在约公元400年。过去认为他就是公元前2世纪的文法家帕坦伽利，此说已为多数学者否定：在11世纪的博阇之前，没有任何文献把两人混为一谈。"},"sources":[{"title":"Wikipedia, “Yoga Sutras of Patanjali” (citing Maas)","url":"https://en.wikipedia.org/wiki/Yoga_Sutras_of_Patanjali"}]},
  {"about":"thinker:ishvarakrishna","verdict":"confirmed","claim":{"en":"Īśvarakṛṣṇa wrote the Sāṃkhyakārikā in the 4th–5th century CE.","zh":"自在黑于公元4至5世纪写成《数论颂》。"},"finding":{"en":"The composition date is unknown, but Paramārtha’s Chinese translation with commentary (557–569 CE) sets a latest date; Gerald Larson places the text in the Gupta period (c. 320–540) and Īśvarakṛṣṇa’s floruit is usually given as c. 350. Wikipedia has no article on him: “Ishvara Krishna” redirects to “Samkhyakarika”, so the link now points there directly.","zh":"成书年代不详，但真谛连同注释的汉译本（557–569年）给出了下限；杰拉尔德·拉森把它放在笈多时代（约320–540年），自在黑的活动年代通常定为约350年。维基百科没有他的独立条目，“Ishvara Krishna”重定向到“Samkhyakarika”，因此链接现在直接指向后者。"},"sources":[{"title":"Wikipedia, “Samkhyakarika” (citing Larson)","url":"https://en.wikipedia.org/wiki/Samkhyakarika"}]},
  {"about":"thinker:shankara","verdict":"corrected","claim":{"en":"Śaṅkara lived c. 700–750; traditionally 788–820.","zh":"商羯罗生活于约700–750年；传统说法为788–820年。"},"finding":{"en":"788–820 is not the tradition’s date but the one early modern scholars proposed. The Stanford Encyclopedia reports that Nakamura argues at length for 700–750 and Potter for the late 7th to early 8th century, and that nothing is reliably known of his life beyond his works. Advaita monastic traditions give dates far earlier still.","zh":"788–820年并非传统说法，而是近代早期学者提出的年代。《斯坦福哲学百科》介绍，中村元详细论证了700–750年之说，波特则主张7世纪末至8世纪初；除了著作之外，他的生平没有可靠的史料。不二论寺院传统给出的年代还要早得多。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Śaṅkara”","url":"https://plato.stanford.edu/entries/shankara/"}]},
  {"about":"thinker:gaudapada","verdict":"confirmed","claim":{"en":"Gauḍapāda (c. 6th century) was by tradition the teacher of Śaṅkara’s teacher.","zh":"乔荼波陀（约6世纪）按传统是商羯罗之师的老师。"},"finding":{"en":"The Stanford Encyclopedia confirms that Śaṅkara’s teacher was named Govinda and that, according to tradition, Govinda’s teacher was Gauḍapāda, of the sixth century CE, author of the Gauḍapādakārikās.","zh":"《斯坦福哲学百科》证实，商羯罗的老师名叫乔频陀；按传统，乔频陀的老师就是6世纪的乔荼波陀，即《蛙氏奥义颂》（又称《圣教论》）的作者。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Śaṅkara”","url":"https://plato.stanford.edu/entries/shankara/"}]},
  {"about":"thinker:madhva","verdict":"contested","claim":{"en":"Madhva lived traditionally 1238–1317.","zh":"摩陀婆的传统生卒年为1238–1317年。"},"finding":{"en":"The Internet Encyclopedia of Philosophy and most specialist accounts (Sharma, Bryant) give 1238–1317, the dates followed in the Madhva tradition. Some reference works give 1199–1278 instead. His biography rests largely on the Madhva-vijaya, written by the son of one of his disciples.","zh":"《互联网哲学百科》与多数专门研究（夏尔马、布莱恩特）都采用1238–1317年，这也是摩陀婆派传统所用的年代；也有一些工具书给出1199–1278年。他的生平主要依据《摩陀婆胜利记》，作者是他一位弟子的儿子。"},"sources":[{"title":"Internet Encyclopedia of Philosophy, “Madhva”","url":"https://iep.utm.edu/madhva/"},{"title":"Wikipedia, “Madhvacharya” (citing Sharma 2000, Bryant 2007)","url":"https://en.wikipedia.org/wiki/Madhvacharya"}]},
  {"about":"thinker:ramanuja","verdict":"corrected","claim":{"en":"Rāmānuja lived traditionally 1017–1137, and is plotted on those dates.","zh":"罗摩奴阇的传统生卒年为1017–1137年，图上也按此放置。"},"finding":{"en":"Tradition gives him a life of 120 years (1017–1137); recent scholarship, following John Carman, places him between 1077 and 1157. The atlas now plots him on the scholarly dates and gives both.","zh":"传统说他享年120岁（1017–1137年）；近来的学界研究依循约翰·卡曼，把他定在1077–1157年。本图谱现按学界年代放置，并同时给出两种说法。"},"sources":[{"title":"Internet Encyclopedia of Philosophy, “Rāmānuja”","url":"https://iep.utm.edu/ramanuja/"}]},
  {"about":"thinker:jayarashi","verdict":"contested","claim":{"en":"Jayarāśi flourished c. 800 and is linked to the Lokāyata tradition, though his scepticism goes beyond standard Cārvāka materialism.","zh":"阇耶罗希约活跃于800年前后，与顺世论传统有关联，但其怀疑论超出了一般的顺世论唯物主义。"},"finding":{"en":"Datings range from Saṃghavī’s 725–825 and Franco’s 770–830 to the 800–840 proposed in the Stanford Encyclopedia. His affiliation is debated: some read the Tattvopaplavasiṃha as a Lokāyata work, others deny he was a materialist; the encyclopedia calls him a ‘qualified sceptic’ and an atypical offshoot of the Cārvāka tradition, which matches the atlas. The title is variously rendered ‘The Lion [Destroying] the Delusion of Categories’ or ‘The Lion which Annihilates [all] Principles’.","zh":"年代推定从桑格维的725–825年、弗朗哥的770–830年，到《斯坦福哲学百科》提出的800–840年不等。他的归属也有争议：有人把《吞噬一切范畴之狮》视为顺世论著作，也有人否认他是唯物论者；该百科称他为“有保留的怀疑论者”、顺世论传统中不典型的旁支，与本图谱的描述相符。书名的译法也不统一，如“摧破范畴迷执之狮”或“灭尽一切原理之狮”。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Jayarāśi”","url":"https://plato.stanford.edu/entries/jayaraasi/"}]},
  {"about":"thinker:dharmakirti","verdict":"contested","claim":{"en":"Dharmakīrti lived c. 600–660.","zh":"法称生活于约600–660年。"},"finding":{"en":"The 600–660 dating is Frauwallner’s, resting on an argument from silence. Krasser, drawing on links with Bhāviveka and Kumārila, pushes his activity back to the mid-6th century, and Balcerowicz proposes 550–610. The Stanford Encyclopedia counsels caution or even agnosticism; the Chinese pilgrim Yijing (in India 675–685) mentions him, Xuanzang (629–645) does not.","zh":"600–660年之说出自弗劳瓦尔纳，依据的是默证。克拉瑟根据法称与清辨、鸠摩利罗的关联，把他的活动提前到6世纪中叶；巴尔采罗维奇则主张550–610年。《斯坦福哲学百科》建议对此保持审慎，甚至存疑；中国求法僧义净（675–685年在印度）提到过他，玄奘（629–645年）却没有。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Dharmakīrti”","url":"https://plato.stanford.edu/entries/dharmakiirti/"}]},
  {"about":"tie:kumarila>dharmakirti","verdict":"contested","claim":{"en":"Dharmakīrti answered Mīmāṃsā arguments for an authorless Veda and against omniscience, Kumārila’s among them.","zh":"法称回应了弥曼差派关于吠陀无作者、反对全知的论证，其中包括鸠摩利罗的论证。"},"finding":{"en":"The Stanford Encyclopedia dates Kumārila’s floruit to around 660, late in the 7th century, while Dharmakīrti’s dates are disputed (mid-6th to mid-7th century). The two certainly argued over the same questions—an authorless Veda, omniscience, word meaning—but who answered whom depends on that unresolved chronology, so the atlas now says so.","zh":"《斯坦福哲学百科》把鸠摩利罗的活动年代定在约660年，即7世纪后期；而法称的年代存在争议（6世纪中叶至7世纪中叶）。两人确实就同样的问题——吠陀无作者、全知、语词的意义——针锋相对，但究竟谁回应谁，取决于这一尚未解决的年代问题，本图谱现已注明。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Kumārila”","url":"https://plato.stanford.edu/entries/kumaarila/"},{"title":"Stanford Encyclopedia of Philosophy, “Dharmakīrti”","url":"https://plato.stanford.edu/entries/dharmakiirti/"}]},
  {"about":"thinker:vasubandhu","verdict":"contested","claim":{"en":"Vasubandhu lived c. 4th–5th century CE and was Asaṅga’s younger half-brother.","zh":"世亲生活于约公元4至5世纪，是无著的同父异母弟弟。"},"finding":{"en":"The Stanford Encyclopedia dates him to the 4th to 5th century, partly on Paramārtha’s report that he taught at the court of a ‘Vikramāditya’ often identified with Chandragupta II (r. 380–415), and confirms that Asaṅga was his elder half-brother who won him over to Yogācāra. Frauwallner’s theory that two Vasubandhus were merged into one still has supporters.","zh":"《斯坦福哲学百科》把他定在4至5世纪，部分依据是真谛的记载：他曾在一位“超日王”的宫廷讲学，此王常被认为是旃陀罗笈多二世（380–415年在位）。该百科也证实，无著是他的同父异母兄长，并说服他转向瑜伽行派。弗劳瓦尔纳认为传统把两位世亲混为一人，此说至今仍有支持者。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Vasubandhu”","url":"https://plato.stanford.edu/entries/vasubandhu/"}]},
  {"about":"tie:uddalaka>yajnavalkya","verdict":"confirmed","claim":{"en":"The Upanishadic teacher lists name Yājñavalkya as Uddālaka’s pupil, though they also clash in debate.","zh":"奥义书的师承谱系把耶若婆佉列为乌达罗迦的弟子，但两人在辩论中也针锋相对。"},"finding":{"en":"Macdonell and Keith’s Vedic Index, cited by Wikipedia, makes Yājñavalkya the pupil of Uddālaka Āruṇi, whom he later defeats at King Janaka’s court. Other traditions name Vaiśampāyana as his teacher in the Yajurveda. Nothing is known of either man’s dates; the Bṛhadāraṇyaka Upaniṣad is dated c. 700 BCE.","zh":"维基百科引用麦克唐奈与基思的《吠陀索引》，称耶若婆佉是乌达罗迦·阿鲁尼的弟子，后来在遮那迦王的宫廷辩论中胜过了老师。另有传统把毗商波衍那列为他在《夜柔吠陀》上的老师。两人的生卒年都无从考证；《广林奥义书》约成书于公元前700年。"},"sources":[{"title":"Wikipedia, “Yajnavalkya” (citing Macdonell & Keith, Vedic Index)","url":"https://en.wikipedia.org/wiki/Yajnavalkya"}]},
  {"about":"thinker:yajnavalkya","verdict":"corrected","claim":{"en":"The atlas names Yājñavalkya 耶若伏吉耶 and Uddālaka 乌达罗迦·阿鲁尼 in Chinese, and plots both with placeholder years.","zh":"本图谱的中文译名为耶若伏吉耶、乌达罗迦·阿鲁尼，并以占位年份标在图上。"},"finding":{"en":"Chinese renderings of Sanskrit names are not standardised. Chinese Wikipedia uses 耶若婆佉 for Yājñavalkya, the older Buddhist-style transliteration; 耶若伏吉耶 and 乌达罗迦·阿鲁尼 follow modern Upaniṣad translations, which we could not open to confirm. Neither man has recorded dates: the numbers on the map only place them in the 8th–7th century BCE, as the dates shown in their entries say. The atlas now uses 耶若婆佉, as Chinese Wikipedia does, so the name matches what readers will search for.","zh":"梵文人名的中文译法并不统一。中文维基百科把Yājñavalkya译作“耶若婆佉”，属于较早的佛典式音译；“耶若伏吉耶”“乌达罗迦·阿鲁尼”沿用现代奥义书译本，我们未能查到原书核实。两人都没有可考的生卒年：图上的数字只是把他们放在公元前8至7世纪，条目中显示的年代已如实说明。本图谱现改用“耶若婆佉”，与中文维基百科一致，便于读者检索。"},"sources":[{"title":"中文维基百科，“耶若婆佉”","url":"https://zh.wikipedia.org/wiki/耶若婆佉"},{"title":"Wikipedia, “Yajnavalkya”","url":"https://en.wikipedia.org/wiki/Yajnavalkya"}]},
  {"about":"tie:vivekananda>aurobindo","verdict":"confirmed","claim":{"en":"Aurobindo said that Vivekananda’s presence came to him in meditation while he was in Alipore jail.","zh":"阿罗频多说，他在阿里浦尔监狱冥想时感到辨喜的临在。"},"finding":{"en":"In a letter of 13 September 1946 Sri Aurobindo wrote that he heard ‘constantly the voice of Vivekananda speaking to me for a fortnight in the jail in my solitary meditation’ and ‘felt his presence’, on a limited field of spiritual experience. It is his own later account, as the atlas implies, of his 1908–09 imprisonment in the Alipore bomb case.","zh":"阿罗频多在1946年9月13日的一封信中写道，他在狱中独自冥想时，“有两周时间不断听到辨喜的声音在对我说话”，并“感到他的临在”，所谈仅限于某一特定的灵性经验领域。这是他本人事后对1908–1909年因阿里浦尔炸弹案入狱经历的回忆，与本图谱的表述一致。"},"sources":[{"title":"Sri Aurobindo, letter of 13 September 1946 (Letters on Himself and the Ashram)","url":"https://sri-aurobindo.co.in/workings/letters/0007/006348_e.htm"}]},
  {"about":"tie:mahavira>gandhi","verdict":"confirmed","claim":{"en":"Gandhi’s non-violence drew on Gujarat’s Jain culture, especially his Jain friend and mentor Raychandbhai.","zh":"甘地的非暴力思想汲取了古吉拉特的耆那教文化，尤其是他的耆那教朋友和导师赖昌德拜。"},"finding":{"en":"Gandhi’s Autobiography devotes a chapter to Raychandbhai (Shrimad Rajchandra), the Jain poet and thinker he met on landing in Bombay in 1891. He names him first among ‘three moderns’ who left a deep impress on his life, with Tolstoy and Ruskin, and calls him his refuge in moments of spiritual crisis, though not his guru.","zh":"甘地在自传中专门写了一章《赖昌德拜》，记述这位耆那教诗人与思想家（室利·拉吉昌德拉），两人于1891年甘地回到孟买当天相识。甘地把他列为“深刻影响了我一生的三位近人”之首，另两位是托尔斯泰与罗斯金，并说他是自己灵性危机时的依靠，但并未奉他为上师。"},"sources":[{"title":"M. K. Gandhi, An Autobiography, Part II, ch. 1, “Raychandbhai”","url":"https://franpritchett.com/00litlinks/gandhi/part2/201chapter.html"}]},
  {"about":"tie:dewey>ambedkar","verdict":"confirmed","claim":{"en":"Ambedkar studied under John Dewey at Columbia University (1913–16) and drew on his ideas of democracy.","zh":"安贝德卡尔1913–1916年在哥伦比亚大学师从约翰·杜威，并吸收了他的民主思想。"},"finding":{"en":"Ambedkar studied at Columbia from 1913 to 1916 (MA 1915) and in Annihilation of Caste (1936) calls ‘Prof. John Dewey, who was my teacher and to whom I owe so much’. His formal dissertation adviser was the economist Edwin Seligman, so ‘taught’ means he took Dewey’s classes, not that Dewey supervised him.","zh":"安贝德卡尔1913–1916年就读于哥伦比亚大学（1915年获硕士学位），并在《消灭种姓》（1936年）中称“约翰·杜威教授是我的老师，我受惠于他良多”。他的论文正式导师是经济学家埃德温·塞利格曼，所以这里的“师承”指他上过杜威的课，而非杜威指导其论文。"},"sources":[{"title":"Frances Pritchett, Ambedkar timeline, 1910s (Columbia University)","url":"https://franpritchett.com/00ambedkar/timeline/1910s.html"}]},
  {"about":"thinker:vivekananda","verdict":"confirmed","claim":{"en":"A disciple of Ramakrishna, Vivekananda presented Vedānta at the 1893 Parliament of the World’s Religions in Chicago; Raja Yoga appeared in 1896.","zh":"辨喜是罗摩克里希那的弟子，1893年在芝加哥世界宗教议会上介绍吠檀多；《王瑜伽》出版于1896年。"},"finding":{"en":"He first met Ramakrishna in 1881 (or early 1882), spoke at the opening of the Parliament on 11 September 1893, published Raja Yoga in 1896, and lived 12 January 1863 – 4 July 1902.","zh":"他于1881年（或1882年初）初见罗摩克里希那，1893年9月11日在议会开幕时演讲，1896年出版《王瑜伽》，生于1863年1月12日，卒于1902年7月4日。"},"sources":[{"title":"Wikipedia, “Swami Vivekananda”","url":"https://en.wikipedia.org/wiki/Swami_Vivekananda"}]},
  {"about":"thinker:laozi","verdict":"contested","claim":{"en":"Laozi is dated “traditionally 6th c. BCE”, and the Daodejing is said to have grown over the 4th–3rd centuries BCE.","zh":"老子的年代标为“传统说法为公元前6世纪”，并称《道德经》形成于公元前4至前3世纪。"},"finding":{"en":"Chinese tradition, following Sima Qian, makes Laozi a senior contemporary of Confucius in the 6th century BCE, but some modern scholars think he is entirely legendary and that his story conflates several figures. Sayings were probably written down from the late 5th century and consolidated in the 4th; bamboo slips from a Guodian tomb of about 300 BCE hold the oldest known parts of the text, which was fairly stable by the mid-3rd century. The years used to place him on the map are placeholders.","zh":"中国传统依司马迁之说，以老子为孔子的前辈、生活于公元前6世纪；但也有现代学者认为老子完全是传说人物，其故事糅合了数人。书中的语录大约自公元前5世纪末开始成文，于前4世纪汇集；郭店一座约公元前300年的楚墓出土的竹简是现存最早的部分文本，至前3世纪中叶文本已大体定型。图上用来定位他的年份只是占位。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Laozi”","url":"https://plato.stanford.edu/entries/laozi/"}]},
  {"about":"thinker:mozi","verdict":"contested","claim":{"en":"Mozi, Shang Yang, Hui Shi, Gongsun Long, Zhuangzi and Xunzi are given conventional birth and death years.","zh":"墨子、商鞅、惠施、公孙龙、庄子、荀子都给出了约定俗成的生卒年。"},"finding":{"en":"None of these dates is secure. Current reference works give: Mozi flourished c. 430 BCE; Shang Yang c. 390–338 BCE; Hui Shi flourished 313 BCE; Gongsun Long c. 320–250 BCE; Zhuangzi flourished in the latter half of the 4th century BCE; Xunzi was born perhaps c. 310 BCE and was still alive in 238 BCE. The atlas’s ranges fall within these and are marked “c.”.","zh":"这些年代都不确定。现今的工具书给出：墨子活跃于约公元前430年；商鞅约前390–前338年；惠施活跃于前313年前后；公孙龙约前320–前250年；庄子活跃于前4世纪后半叶；荀子约生于前310年，前238年时仍在世。本图谱的年代都落在这些范围之内，并标有“约”字。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Mohism”","url":"https://plato.stanford.edu/entries/mohism/"},{"title":"Stanford Encyclopedia of Philosophy, “School of Names”","url":"https://plato.stanford.edu/entries/school-names/"},{"title":"Stanford Encyclopedia of Philosophy, “Xunzi”","url":"https://plato.stanford.edu/entries/xunzi/"}]},
  {"about":"thinker:shang-yang","verdict":"corrected","claim":{"en":"After Duke Xiao died, Shang Yang “was executed by being torn apart by chariots”.","zh":"孝公死后，商鞅“被车裂处死”。"},"finding":{"en":"Sima Qian’s Records of the Grand Historian says Qin troops attacked Shang Yang and killed him at Mianchi in Zheng, and King Hui of Qin then had his body torn apart by chariots as a public warning. Later retellings often say he was torn apart alive.","zh":"司马迁《史记·商君列传》记载：“秦发兵攻商君，杀之于郑黾池。秦惠王车裂商君以徇。”也就是说，他先被秦军所杀，死后遭车裂示众；后世常说他是被活活车裂的。"},"sources":[{"title":"Sima Qian, Shiji, chapter 68, “Biography of Lord Shang” (Wikisource)","url":"https://zh.wikisource.org/wiki/史記/卷068"},{"title":"Wikipedia, “Shang Yang”","url":"https://en.wikipedia.org/wiki/Shang_Yang"}]},
  {"about":"school:confucianism","verdict":"contested","claim":{"en":"Dong Zhongshu is listed as the author of the Luxuriant Dew of the Spring and Autumn Annals (“attributed”, c. 110 BCE).","zh":"《春秋繁露》署为董仲舒所作（“托名”，约公元前110年）。"},"finding":{"en":"The attribution has been doubted since the Song dynasty, Zhu Xi among the sceptics. The 82-chapter work is undated and is now usually treated as a collection of loosely related Han-dynasty chapters; some parts may reflect Dong’s teaching, others are later. The year is only a placeholder for “Western Han”.","zh":"这一归属自宋代起就受到怀疑，朱熹即为质疑者之一。全书八十二篇，未署年代，今人一般视为若干汉代篇章的汇编：其中一些可能反映董仲舒的学说，另一些则出自更晚。所标年份只是“西汉”的占位。"},"sources":[{"title":"Wikipedia, “Luxuriant Dew of the Spring and Autumn Annals”","url":"https://en.wikipedia.org/wiki/Luxuriant_Dew_of_the_Spring_and_Autumn_Annals"}]},
  {"about":"thinker:huineng","verdict":"confirmed","claim":{"en":"The Platform Sutra is dated c. 780 and described as attributed to Huineng but compiled by followers.","zh":"《六祖坛经》定为约780年，并说明它托名慧能、实由后学编成。"},"finding":{"en":"The earliest known version, preserved at Dunhuang, dates from about 780, almost seventy years after Huineng’s death, and later editions are more than twice as long. Its story is demonstrably unhistorical in places and only makes sense after Shenhui’s campaign to have Huineng recognised as the Sixth Patriarch; its editor may have belonged to the Oxhead school.","zh":"已知最早的版本保存在敦煌写本中，约成于780年，距慧能去世已近七十年；后世通行本的篇幅是它的两倍多。书中的故事有些地方明显不合史实，而且只有在神会极力推举慧能为六祖之后才说得通；最早的编者可能属于牛头宗。"},"sources":[{"title":"Encyclopedia of Religion, “Huineng” (on Encyclopedia.com)","url":"https://www.encyclopedia.com/environment/encyclopedias-almanacs-transcripts-and-maps/huineng"}]},
  {"about":"thinker:zhang-zai","verdict":"confirmed","claim":{"en":"The Western Inscription is dated c. 1070, and Correcting the Unenlightened 1076.","zh":"《西铭》定为约1070年，《正蒙》定为1076年。"},"finding":{"en":"Zhang Zai completed Correcting the Unenlightened (Zhengmeng) in 1076. The Western Inscription, first called “Correcting Obstinacy” (Ding wan) and hung on the western wall of his study, has no exact date; it was written in his last years and later placed in the Zhengmeng, so “c. 1070” is an approximation.","zh":"张载于1076年撰成《正蒙》。《西铭》原名《订顽》，书于学堂西牖，没有确切的写作年份；它写于张载晚年，后被收入《正蒙》，所以“约1070年”只是近似。"},"sources":[{"title":"Wikipedia (Chinese), “張載 (北宋)”","url":"https://zh.wikipedia.org/wiki/張載_(北宋)"}]},
  {"about":"tie:zhang-zai>cheng-hao","verdict":"corrected","claim":{"en":"Zhang Zai is called the Cheng brothers’ “uncle by family ties”.","zh":"张载被称为二程“家族上的叔辈”。"},"finding":{"en":"Zhang Zai was the brothers’ biaoshu (表叔), an uncle through a cousin’s line, one generation above them: they were his biaozhi, and the three are remembered as kinsmen of one mind.","zh":"张载是二程的表叔，比他们长一辈；二程是他的表侄，三人被称为“表叔侄三人志同道合”。"},"sources":[{"title":"Wikipedia (Chinese), “張載 (北宋)”","url":"https://zh.wikipedia.org/wiki/張載_(北宋)"}]},
  {"about":"thinker:cheng-hao","verdict":"corrected","claim":{"en":"Cheng Hao’s “On Understanding Humaneness” is dated 1080.","zh":"程颢《识仁篇》定为1080年。"},"finding":{"en":"The piece is preserved in the Surviving Works of the Two Chengs (book 2A) as Cheng Hao’s answer to Lü Dalin, who came east to study with the brothers after Zhang Zai’s death; Lü’s record of that visit is dated 1079. The year is therefore better given as c. 1079.","zh":"此篇见于《二程遗书》卷二上，是程颢回答吕大临（与叔）问功夫之语。吕大临在张载去世后东见二程，所记《东见录》在元丰二年（1079年），因此宜作约1079年。"},"sources":[{"title":"曾亦、郭晓东：《程明道：本体即功夫，功夫即本体》（儒家网）","url":"https://www.rujiazg.com/article/6609"},{"title":"曹树明，《哲学动态》2018年第7期（搜狐转载）","url":"https://www.sohu.com/a/257529997_273853"}]},
  {"about":"school:school-of-names","verdict":"corrected","claim":{"en":"The “All Under Heaven” chapter of the Zhuangzi, which preserves Hui Shi’s paradoxes, is listed as Zhuangzi’s work of c. 250 BCE.","zh":"保存惠施“历物十事”的《庄子·天下》被列为庄子之作，约公元前250年。"},"finding":{"en":"Since Guo Xiang, only the Inner Chapters have been associated with Zhuangzi himself; “All Under Heaven” is chapter 33, in the Miscellaneous group, and probably dates from the first decades of the Han dynasty. Hui Shi’s own writings are lost.","zh":"自郭象以来，只有内篇被认为与庄子本人有关；《天下》是第三十三篇，属杂篇，大概写于汉初数十年间。惠施本人的著作已经失传。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “School of Names”","url":"https://plato.stanford.edu/entries/school-names/"},{"title":"Stanford Encyclopedia of Philosophy, “Zhuangzi”","url":"https://plato.stanford.edu/entries/zhuangzi/"}]},
  {"about":"school:mohism","verdict":"corrected","claim":{"en":"The Mozi’s “Impartial Care” and “Against Offensive War” chapters are listed as Mozi’s work.","zh":"《墨子》的《兼爱》《非攻》各篇被列为墨子所作。"},"finding":{"en":"The Mozi is a collection of anonymous texts from the 5th to the 3rd century BCE. The core chapters, each surviving in up to three versions, record the doctrines of Mozi’s movement as written down by his followers, not by Mozi himself.","zh":"《墨子》是公元前5至前3世纪的一批佚名文本的汇编。核心各篇（多有上中下三个版本）记录的是墨家学派的主张，由其后学写成，并非墨子亲笔。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Mohism”","url":"https://plato.stanford.edu/entries/mohism/"}]},
  {"about":"link:mohism>school-of-names","verdict":"contested","claim":{"en":"Mohism is linked to the School of Names as a borrowing: the Mohist canons answer paradoxes like “a white horse is not a horse”.","zh":"墨家与名家之间标为“借鉴”：墨家的《墨经》回应了“白马非马”之类的论题。"},"finding":{"en":"The later Mohist Dialectics contain passages that seem to rebut the disputers’ ideas, and the Zhuangzi’s “All Under Heaven” shows Mohist sects debating the same “hard and white” and “same and different” themes. Who influenced whom is not recorded; the line marks shared problems.","zh":"后期墨家的《墨辩》中有些段落像是在反驳辩者的观点，《庄子·天下》也描写墨家各派辩论“坚白”“同异”这些相同的题目。但谁影响了谁并无记载；这条线表示的是共同的问题。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “School of Names”","url":"https://plato.stanford.edu/entries/school-names/"}]},
  {"about":"tie:hui-shi>gongsun-long","verdict":"uncertain","claim":{"en":"Hui Shi is shown as an influence on Gongsun Long.","zh":"图谱中惠施被标为影响了公孙龙。"},"finding":{"en":"Both are counted among the disputers (bianzhe) and the later tradition groups them as the School of Names, but no source records that they met or that Gongsun Long learned from Hui Shi. The tie marks a shared line of argument, not a documented contact.","zh":"二人都属于“辩者”，后世把他们一起归入名家，但没有任何材料记载他们见过面，或公孙龙曾向惠施学习。这条关系表示的是同一条论辩路线，而非有记载的交往。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “School of Names”","url":"https://plato.stanford.edu/entries/school-names/"}]},
  {"about":"school:xinxue","verdict":"corrected","claim":{"en":"The School of Mind is drawn from the 12th to the 17th century, ending in 1700.","zh":"心学被画在12至17世纪，止于1700年。"},"finding":{"en":"Wang Yangming learning (Yōmeigaku) went on in Japan: Nakae Tōju (1608–1648) and Kumazawa Banzan (1619–1691) in the 17th century, and a line of “Yangmingists” from Ōshio Heihachirō’s Osaka uprising of 1837 into the Meiji era and beyond. The end date is moved to the late 19th century.","zh":"阳明学在日本延续了下来：17世纪有中江藤树（1608–1648）与熊泽蕃山（1619–1691），此后从1837年大盐平八郎的大阪起义一直到明治时代乃至更晚，都有自认的“阳明学者”。因此终止年份改为19世纪末。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Japanese Confucian Philosophy”","url":"https://plato.stanford.edu/entries/japanese-confucian/"},{"title":"University of Tokyo, review of Kojima Tsuyoshi, The Wang Yangming School in Modern Japan","url":"https://www.u-tokyo.ac.jp/biblioplaza/en/K_00060.html"}]},
  {"about":"school:kyoto","verdict":"corrected","claim":{"en":"The Kyoto School is drawn from 1911 to 1990, the year Nishitani died.","zh":"京都学派被画在1911年至1990年（西谷启治去世之年）。"},"finding":{"en":"The school was never a formal organisation; it is usually described as philosophers spanning several generations: Nishida and Tanabe; then Hisamatsu, Nishitani and others; then Takeuchi, Tsujimura and Ueda. The Stanford Encyclopedia describes it today as both an object of scholarship and a living tradition, so it is now drawn to the present.","zh":"京都学派从来不是正式的组织，通常被描述为跨越数代的一批哲学家：第一代西田与田边，第二代久松、西谷等人，第三代武内、辻村、上田等人。《斯坦福哲学百科》认为它今天既是研究对象，也是一个活着的传统，因此改为延续至今。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “The Kyoto School”","url":"https://plato.stanford.edu/entries/kyoto-school/"}]},
  {"about":"thinker:nishitani","verdict":"corrected","claim":{"en":"Nishitani’s 1949 book is given as “The Self-Overcoming of Nihilism” (《虚无主义》).","zh":"西谷启治1949年的著作写作《The Self-Overcoming of Nihilism》（《虚无主义》）。"},"finding":{"en":"The 1949 book (Tokyo: Kōbundō) is titled simply Nihirizumu (Nihilism); “The Self-Overcoming of Nihilism” is the title of Graham Parkes and Setsuko Aihara’s English translation (SUNY Press, 1990). His 1961 Shūkyō to wa nanika (What Is Religion?) is known in English as Religion and Nothingness, translated by Jan Van Bragt (1982).","zh":"这本1949年的书（东京：弘文堂）原题就是《ニヒリズム》（《虚无主义》）；《The Self-Overcoming of Nihilism》是Graham Parkes与相原节子1990年英译本（纽约州立大学出版社）的书名。他1961年的《宗教とは何か》（《宗教是什么》）由Jan Van Bragt英译，1982年出版，题为《Religion and Nothingness》。"},"sources":[{"title":"Wikipedia, “Keiji Nishitani” (list of collected works)","url":"https://en.wikipedia.org/wiki/Keiji_Nishitani"},{"title":"Kyushu University Library catalogue, The Self-Overcoming of Nihilism (原タイトル: ニヒリズム)","url":"https://catalog.lib.kyushu-u.ac.jp/ja/recordID/1000097736"},{"title":"SUNY Press, The Self-Overcoming of Nihilism","url":"https://sunypress.edu/Books/T/The-Self-Overcoming-of-Nihilism"}]},
  {"about":"thinker:tanabe","verdict":"confirmed","claim":{"en":"Brought to Kyoto by Nishida, Tanabe openly criticised his senior’s philosophy from 1930.","zh":"田边元由西田引荐到京都，自1930年起公开批评西田的哲学。"},"finding":{"en":"Tanabe’s 1930 essay “Requesting Instruction from Professor Nishida” opened his public criticism of Nishida’s philosophy of place.","zh":"田边1930年发表《仰西田先生之教》，由此开始公开批评西田的场所哲学。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “The Kyoto School”","url":"https://plato.stanford.edu/entries/kyoto-school/"}]},
  {"about":"tie:xunzi>han-feizi","verdict":"confirmed","claim":{"en":"Xunzi taught Han Fei, and his “Human Nature Is Bad” chapter argues against Mencius.","zh":"荀子是韩非的老师，《性恶》篇针对孟子而发。"},"finding":{"en":"Han Fei (d. 233 BCE) and Li Si (d. 208 BCE) are recorded among Xunzi’s former students. The “Human Nature Is Bad” chapter is framed as an argument with Mencius, who was probably long dead; its title may not be Xunzi’s own.","zh":"韩非（卒于前233年）与李斯（卒于前208年）都被记载为荀子的学生。《性恶》篇以与孟子论辩的形式写成，而那时孟子大概早已去世；篇名也未必出自荀子本人。"},"sources":[{"title":"Stanford Encyclopedia of Philosophy, “Xunzi”","url":"https://plato.stanford.edu/entries/xunzi/"}]},
  {"about": "thinker:zeno-elea", "verdict": "corrected", "claim": {"en": "Zeno’s book of paradoxes can be dated to 460 BCE.", "zh": "芝诺的悖论之书可定年于公元前460年。"}, "finding": {"en": "Nothing dates the book. Plato’s Parmenides has the young Zeno read it in Athens, but that is a dramatic setting, not a date. The arguments survive through Aristotle’s Physics and through Simplicius, who quotes Zeno’s own words. The atlas now gives no year and names both sources.", "zh": "此书无从定年。柏拉图《巴门尼德篇》写年轻的芝诺在雅典朗读此书，但那是对话的场景设定，不是年代证据。这些论证靠亚里士多德的《物理学》和辛普里丘流传下来，后者还引用了芝诺的原话。图谱现在不给年份，并注明这两处来源。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Zeno of Elea”", "url": "https://plato.stanford.edu/entries/zeno-elea/"}, {"title": "Internet Encyclopedia of Philosophy, “Zeno’s Paradoxes”", "url": "https://iep.utm.edu/zenos-paradoxes/"}]},
  {"about": "thinker:democritus", "verdict": "corrected", "claim": {"en": "Democritus’ fragments on ethics and nature date from about 400 BCE.", "zh": "德谟克利特的伦理与自然残篇约写于公元前400年。"}, "finding": {"en": "Diogenes Laertius lists some seventy works, but none can be placed within Democritus’ long life (c. 460–c. 370 BCE), and what survives is a scatter of quotations. A single year for “the fragments” was a plotting guess; the atlas now gives none.", "zh": "第欧根尼·拉尔修列出约七十部著作，但没有一部能在德谟克利特漫长的一生（约前460–约前370年）中定位，传世的只是零散的引文。给“残篇”一个年份只是为了画图而作的估计，图谱现在不再给出年份。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Democritus”", "url": "https://plato.stanford.edu/entries/democritus/"}, {"title": "Stanford Encyclopedia of Philosophy, “Ancient Atomism”", "url": "https://plato.stanford.edu/entries/atomism-ancient/"}]},
  {"about": "thinker:dong-zhongshu", "verdict": "corrected", "claim": {"en": "Luxuriant Dew of the Spring and Autumn Annals dates from about 110 BCE.", "zh": "《春秋繁露》约成书于公元前110年。"}, "finding": {"en": "The title is first recorded centuries after Dong Zhongshu, and the text as we have it was compiled later from writings by him and by others; scholars place the compilation as late as the 4th–6th centuries CE. Since the atlas already calls it a later compilation, it no longer gives it a year.", "zh": "此书名在董仲舒身后数百年才见于著录，今本是后人把他和其他人的文字汇编而成的；学者认为汇编可能晚至公元4至6世纪。图谱既已注明它是后人汇编，便不再给出年份。"}, "sources": [{"title": "Wikipedia, “Luxuriant Dew of the Spring and Autumn Annals”", "url": "https://en.wikipedia.org/wiki/Luxuriant_Dew_of_the_Spring_and_Autumn_Annals"}, {"title": "Stanford Encyclopedia of Philosophy, “Philosophy in Han Dynasty China”", "url": "https://plato.stanford.edu/entries/han-dynasty/"}]},
  {"about": "thinker:xunzi", "verdict": "corrected", "claim": {"en": "Xunzi died in 235 BCE.", "zh": "荀子卒于公元前235年。"}, "finding": {"en": "The one firm point is that he outlived his patron Lord Chunshen, assassinated in 238 BCE, after which he lost his post at Lanling. Reference works give c. 235 or c. 230 for his death; the atlas now says “after 238 BCE” and keeps 235 only as a plotting year.", "zh": "唯一可靠的是，他比自己的庇护者春申君活得久：春申君于公元前238年遇刺，荀子随后失去兰陵令之职。工具书给出的卒年有约前235年和约前230年两说；图谱现在写作“前238年后”，只把前235年留作画图用的年份。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Xunzi”", "url": "https://plato.stanford.edu/entries/xunzi/"}, {"title": "World History Encyclopedia, “Xunzi”", "url": "https://www.worldhistory.org/Xunzi/"}]},
  {"about": "school:kalam", "verdict": "corrected", "claim": {"en": "The Abbasid inquisition (miḥna) lasted from 833 to 848.", "zh": "阿拔斯王朝的“米哈奈”审查从833年持续到848年。"}, "finding": {"en": "The start, al-Maʾmūn’s letter of 833, is secure. The end came gradually under al-Mutawakkil and is dated variously: Britannica says about 848, other surveys 849 or 851–52. The atlas now gives “c. 848”.", "zh": "起点，即马蒙833年的诏令，是确定的。结束则是穆塔瓦基勒在位时逐步发生的，年代说法不一：大英百科全书作约848年，其他综述作849年或851–852年。图谱现在写作“约848年”。"}, "sources": [{"title": "Britannica, “Miḥnah”", "url": "https://www.britannica.com/topic/mihnah"}, {"title": "Wikipedia, “Mihna”", "url": "https://en.wikipedia.org/wiki/Mihna"}]},
  {"about": "school:early-analytic", "verdict": "corrected", "claim": {"en": "Russell and Moore broke with British idealism around 1900.", "zh": "罗素与摩尔约在1900年与英国唯心论决裂。"}, "finding": {"en": "Russell dated it himself: “It was towards the end of 1898 that Moore and I rebelled against both Kant and Hegel.” Moore’s “The Nature of Judgment” (1899) and “The Refutation of Idealism” (1903) followed. The atlas now says “from 1898”, matching the Moore–Russell tie.", "zh": "罗素自己给出了时间：“大约在1898年底，摩尔和我起来反叛康德和黑格尔。”随后有摩尔的《判断的本质》（1899）和《驳唯心论》（1903）。图谱现在写作“1898年起”，与摩尔—罗素一条的说法一致。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Bertrand Russell”", "url": "https://plato.stanford.edu/entries/russell/"}, {"title": "The Cambridge Companion to Bertrand Russell, “Russell and Moore, 1898–1905”", "url": "https://www.cambridge.org/core/books/abs/cambridge-companion-to-bertrand-russell/russell-and-moore-18981905/03425ABC51AB7AB1EAC9FBC58217EAEE"}]},
  {"about": "thinker:anaxagoras", "verdict": "contested", "claim": {"en": "Anaxagoras settled in Athens around 460 BCE.", "zh": "阿那克萨戈拉约在公元前460年定居雅典。"}, "finding": {"en": "Diogenes Laertius’ figures conflict, and modern scholars have proposed arrival dates from about 480 to 456 BCE, with different lengths for his stay. 460 is one common estimate, not a settled date, so the atlas now marks it as disputed.", "zh": "第欧根尼·拉尔修给出的数字互相矛盾，现代学者提出的抵达年代从约前480年到前456年不等，对他在雅典居留的时长也看法不一。前460年只是常见的估计之一，并非定论，图谱现在注明年代有争议。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Anaxagoras”", "url": "https://plato.stanford.edu/entries/anaxagoras/"}, {"title": "Internet Encyclopedia of Philosophy, “Anaxagoras”", "url": "https://iep.utm.edu/anaxagoras/"}]},
  {"about": "thinker:voltaire", "verdict": "corrected", "claim": {"en": "Voltaire’s Letters on the English (1733) was burned by order of the Paris parlement.", "zh": "伏尔泰的《哲学通信》（1733）被巴黎高等法院下令焚毁。"}, "finding": {"en": "The book first appeared in English in London in 1733. The French text, the Lettres philosophiques, came out in 1734, and it was this edition that the Paris parlement condemned and had burned that June. Both dates are now given.", "zh": "此书1733年先以英文在伦敦出版；法文本《哲学通信》1734年问世，被巴黎高等法院定罪、当年6月下令焚毁的正是这个法文本。图谱现在两个年份都标出。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Voltaire”", "url": "https://plato.stanford.edu/entries/voltaire/"}, {"title": "Wikipedia, “Letters on the English”", "url": "https://en.wikipedia.org/wiki/Letters_on_the_English"}]},
  {"about": "thinker:nishida", "verdict": "corrected", "claim": {"en": "Nishida died in June 1945, weeks before Japan’s surrender.", "zh": "西田于1945年6月去世，距日本投降只有几周。"}, "finding": {"en": "He died in Kamakura on 7 June 1945; Japan announced its surrender on 15 August, ten weeks later. The atlas now says “about two months”.", "zh": "他于1945年6月7日在镰仓去世；日本于8月15日宣布投降，相隔十周。图谱现在写作“约两个月”。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Nishida Kitarō”", "url": "https://plato.stanford.edu/entries/nishida-kitaro/"}, {"title": "Encyclopedia.com, “Nishida Kitarō”", "url": "https://www.encyclopedia.com/environment/encyclopedias-almanacs-transcripts-and-maps/nishida-kitaro"}]},
  {"about": "thinker:barthes", "verdict": "corrected", "claim": {"en": "Barthes died after being struck by a van in a Paris street.", "zh": "巴特在巴黎街头被一辆货车撞倒后去世。"}, "finding": {"en": "He was hit by a laundry van on 25 February 1980, after a lunch with François Mitterrand, and died in hospital on 26 March, of complications affecting lungs already weakened by tuberculosis. The atlas now gives both dates.", "zh": "1980年2月25日，他在与密特朗午餐后被一辆洗衣店货车撞倒，3月26日在医院去世，死因是并发症，他的肺早因结核病而虚弱。图谱现在给出两个日期。"}, "sources": [{"title": "The New York Review of Books, “The Mythologies of R.B.”", "url": "https://www.nybooks.com/articles/2018/06/07/mythologies-of-roland-barthes/"}, {"title": "Britannica, “Roland Barthes”", "url": "https://www.britannica.com/biography/Roland-Barthes"}]},
  {"about": "school:confucianism", "verdict": "corrected", "claim": {"en": "The Analects is a work by Confucius.", "zh": "《论语》是孔子的著作。"}, "finding": {"en": "The Analects records Confucius’ sayings as remembered by his disciples and their students, compiled over several generations; he did not write it. The school page now says “compiled by disciples”, as the Confucius page already did.", "zh": "《论语》记录的是弟子及再传弟子所记忆的孔子言论，历经几代人编成，并非孔子亲笔。学派页现在注明“弟子辑录”，与孔子本人页面的写法一致。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Confucius”", "url": "https://plato.stanford.edu/entries/confucius/"}, {"title": "Wikipedia, “Analects”", "url": "https://en.wikipedia.org/wiki/Analects"}]},
  {"about": "school:yogacara", "verdict": "corrected", "claim": {"en": "Asaṅga and Vasubandhu were brothers who systematised Yogācāra in Gandhāra.", "zh": "无著与世亲兄弟在犍陀罗把瑜伽行派系统化。"}, "finding": {"en": "Tradition, followed by the Stanford Encyclopedia, makes them half-brothers, born in Puruṣapura (Peshawar) in Gandhāra. Their teaching careers, though, are placed further east, in Ayodhyā and elsewhere in northern India, so the atlas now says they came from Gandhāra rather than that they worked there.", "zh": "传统说法（斯坦福哲学百科全书沿用）认为他们是同父异母兄弟，生于犍陀罗的富楼沙（白沙瓦）。但他们的讲学生涯被定位在更东边的阿逾陀等北印度地区，所以图谱现在说他们出身犍陀罗，而不说他们在那里著述。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Yogācāra”", "url": "https://plato.stanford.edu/entries/yogacara/"}, {"title": "Stanford Encyclopedia of Philosophy, “Vasubandhu”", "url": "https://plato.stanford.edu/entries/vasubandhu/"}]},
  {"about": "thinker:yi-i", "verdict": "corrected", "claim": {"en": "After his mother’s death, when he was fifteen, Yi I spent about a year in a Buddhist monastery.", "zh": "李珥十五岁丧母后，在佛寺里待了大约一年。"}, "finding": {"en": "His mother died in 1551. He first kept the customary three years of mourning, and only then, at about eighteen, went to a temple in the Diamond Mountains (Kŭmgangsan) for about a year before returning to Confucian study. The atlas now includes the mourning.", "zh": "他的母亲于1551年去世。他先守了按礼制的三年孝，之后约十八岁时才前往金刚山的寺院，住了约一年，再回到儒学。图谱现在补上了守孝一节。"}, "sources": [{"title": "Encyclopedia of Religion, “Yi Yulgok”", "url": "https://www.encyclopedia.com/environment/encyclopedias-almanacs-transcripts-and-maps/yi-yulgok"}, {"title": "Wikipedia, “Yi I”", "url": "https://en.wikipedia.org/wiki/Yi_I"}]},
  {"about": "thinker:nishida", "verdict": "corrected", "claim": {"en": "Nishida’s 1927 book is From the Acting to the Seeing.", "zh": "西田1927年的著作英文名为From the Acting to the Seeing。"}, "finding": {"en": "Hataraku mono kara miru mono e (1927) is the book in which Nishida first set out his logic of place. In English it is usually cited as From That Which Acts to That Which Sees, as in the Stanford Encyclopedia; the atlas now uses that title. The Chinese title is unchanged.", "zh": "《从动者到见者》（1927）是西田首次提出“场所逻辑”的著作。英文通常引作From That Which Acts to That Which Sees，斯坦福哲学百科全书即如此；图谱的英文书名现已改用这一译法，中文书名不变。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Nishida Kitarō”", "url": "https://plato.stanford.edu/entries/nishida-kitaro/"}]},
  {"about": "thinker:saadia", "verdict": "corrected", "claim": {"en": "Quarrels with the exilarch cost Saadia his post for some years before his death in 942.", "zh": "萨阿迪亚因与流亡首领冲突而失去职位，直到942年去世。"}, "finding": {"en": "The exilarch David ben Zakkai deposed him in about 930. The two were reconciled around 937 and Saadia returned as gaon, holding the office until he died in 942. The atlas now says he was reinstated.", "zh": "约930年，流亡首领大卫·本·扎凯罢免了他。约937年两人和解，萨阿迪亚复任加昂，直到942年去世。图谱现在写明他已复职。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Saadya [Saadiah]”", "url": "https://plato.stanford.edu/entries/saadya/"}, {"title": "Encyclopedia.com, “Saadia ben Joseph al-Fayyumi”", "url": "https://www.encyclopedia.com/people/philosophy-and-religion/judaism-biographies/saadia-ben-joseph-al-fayumi"}]},
  {"about": "thinker:foot", "verdict": "corrected", "claim": {"en": "Foot was an early member of Oxfam.", "zh": "富特是乐施会的早期成员。"}, "finding": {"en": "She is sometimes called a founder, but the earliest record of her involvement is from 1948, six years after the Oxford Committee for Famine Relief was set up; she stayed active in it all her life. The atlas now says that.", "zh": "有时有人称她是创始人之一，但她参与的最早记录是1948年，比牛津饥荒救济委员会成立晚了六年；此后她终身积极参与。图谱现在照此表述。"}, "sources": [{"title": "Stanford Encyclopedia of Philosophy, “Philippa Foot”", "url": "https://plato.stanford.edu/entries/philippa-foot/"}]},
  {"about": "link:confucianism>neo-confucianism", "verdict": "corrected", "claim": {"en": "The Song masters grouped Mencius, the Great Learning, the Analects and the Doctrine of the Mean as the Four Books.", "zh": "宋儒把《孟子》《大学》《论语》《中庸》合为《四书》。"}, "finding": {"en": "The Cheng brothers had already singled out the Great Learning and the Doctrine of the Mean, but it was Zhu Xi who put the four texts together and published his commentaries on them in 1190; from 1313 they were the basis of the civil-service examinations. The note now names him.", "zh": "二程已特别推重《大学》《中庸》，但把四部书合在一起的是朱熹，他于1190年刊行了《四书章句集注》；1313年起，四书成为科举考试的依据。说明现已点出朱熹。"}, "sources": [{"title": "Britannica, “Zhu Xi”", "url": "https://www.britannica.com/biography/Zhu-Xi"}, {"title": "Columbia University, Asia for Educators, “Neo-Confucianism”", "url": "https://afe.easia.columbia.edu/songdynasty-module/confucian-neo.html"}]}
];
